def safe_shutdown_executor(executor, wait=True, cancel_futures=True):
    """Beendet einen Executor sicher, ohne TypeError bei nicht unterstütztem cancel_futures."""
    if executor is None:
        return
    try:
        executor.shutdown(wait=wait, cancel_futures=cancel_futures)
    except TypeError:
        executor.shutdown(wait=wait)
    except Exception as e:
        logger.warning(f"Executor shutdown failed: {e}")


def _parse_debug_args() -> None:
    global DEBUG_LEVEL, QUIET_MODE
    for arg in sys.argv[1:]:
        if arg in ("--quiet", "-q"):
            QUIET_MODE = True
            continue
        if arg == "--debug":
            DEBUG_LEVEL = max(DEBUG_LEVEL, 1)
            continue
        if arg.startswith("--debug="):
            value = arg.split("=", 1)[1]
            if not value:
                continue
            if value.isdigit():
                DEBUG_LEVEL = max(DEBUG_LEVEL, int(value))
                continue
            if value == "all":
                DEBUG_LEVEL = max(DEBUG_LEVEL, 3)
                if "all" not in DEBUG_COMPONENTS:
                    DEBUG_COMPONENTS.append("all")
                continue
            parts = [p.strip() for p in value.split(",") if p.strip()]
            for comp in parts:
                if comp not in DEBUG_COMPONENTS:
                    DEBUG_COMPONENTS.append(comp)


_parse_debug_args()
