def normalize_model_name(name: str) -> str:
    if name is None:
        return ""
    name = name.strip()
    if not name:
        return ""
    name = unicodedata.normalize("NFKC", name)
    hyphens = "‐‑‒–—―−⸺⸻〜"
    trans = str.maketrans(hyphens, "-" * len(hyphens))
    name = name.translate(trans)
    name = " ".join(name.split())
    name = name.lower()
    return name


def resolve_alias(name: str) -> str:
    normalized = normalize_model_name(name)
    return MODEL_ALIASES.get(normalized, normalized)


_available_models_cache: set[str] | None = None
_available_models_cache_time: float = 0.0
_CACHE_TTL: float = 300.0


def get_available_whisper_models(force_refresh: bool = False) -> set[str]:
    global _available_models_cache, _available_models_cache_time

    if not force_refresh and _available_models_cache is not None:
        if time.time() - _available_models_cache_time < _CACHE_TTL:
            return _available_models_cache
    models = {normalize_model_name(m) for m in WHISPER_MODELS_BASE}
    try:
        import whisper

        if hasattr(whisper, "available_models"):
            whisper_models = {
                normalize_model_name(m) for m in whisper.available_models()
            }
            models.update(whisper_models)
    except ImportError:
        pass
    except Exception as e:
        logger.warning(
            f"Fehler beim Laden der Whisper‑Modelle: {e} – verwende statische Liste"
        )
    models.update(normalize_model_name(alias) for alias in MODEL_ALIASES)
    logger.debug(f"[get_available_whisper_models] Normalized models: {models}")
    _available_models_cache = models
    _available_models_cache_time = time.time()
    return models


def get_valid_model(
    model_name: str,
    fallback: str | None = None,
    fallback_chain: list[str] | None = None,
    use_dynamic_list: bool = True,
    force_refresh: bool = False,
) -> str:
    """
    Gibt einen gültigen Modellnamen zurück, nach Normalisierung, Alias-Auflösung
    und Prüfung gegen die verfügbaren Modelle. Bei Ungültigkeit wird die
    Fallback-Kette durchlaufen.
    Returns:
    """
    if model_name is None:
        model_name = ""

    normalized = normalize_model_name(model_name)
    if not normalized:
        return _resolve_fallback(
            fallback, fallback_chain, use_dynamic_list, force_refresh
        )

    canonical = resolve_alias(normalized)

    if use_dynamic_list:
        valid_models = get_available_whisper_models(force_refresh=force_refresh)
    else:
        valid_models = WHISPER_MODELS_BASE

    logger.debug(
        f"[get_valid_model] raw='{model_name}', normalized='{normalized}', "
        f"canonical='{canonical}', in_models={canonical in valid_models}, "
        f"force_refresh={force_refresh}, valid_models_count={len(valid_models)}"
    )

    if canonical in valid_models:
        return canonical

    logger.warning(
        f"⚠️ Unbekanntes Modell '{model_name}' (normalisiert: '{normalized}') – verwende Fallback"
    )
    return _resolve_fallback(fallback, fallback_chain, use_dynamic_list, force_refresh)


def _resolve_fallback(
    fallback: str | None,
    fallback_chain: list[str] | None,
    use_dynamic_list: bool,
) -> str:
    """
    Interne Hilfsfunktion für die Fallback‑Auflösung.
    """
    if fallback:
        return get_valid_model(
            fallback, fallback_chain=None, use_dynamic_list=use_dynamic_list
        )

    chain = fallback_chain if fallback_chain is not None else DEFAULT_FALLBACK_CHAIN
    valid_models = (
        get_available_whisper_models() if use_dynamic_list else WHISPER_MODELS_BASE
    )

    for candidate in chain:
        normalized = normalize_model_name(candidate)
        canonical = resolve_alias(normalized)
        if canonical in valid_models:
            return canonical

    logger.error("❌ Kein Fallback‑Modell gefunden – verwende 'base'")
    return "base"


def add_model_alias(alias: str, canonical: str) -> None:
    """Fügt einen neuen Alias hinzu."""
    MODEL_ALIASES[normalize_model_name(alias)] = canonical


def add_model_name(model: str) -> None:
    """Fügt einen neuen Modellnamen zur Basis‑Liste hinzu."""
    WHISPER_MODELS_BASE.add(normalize_model_name(model))


def set_fallback_chain(chain: list[str]) -> None:
    """Setzt die globale Fallback‑Kette."""
    global DEFAULT_FALLBACK_CHAIN
    DEFAULT_FALLBACK_CHAIN = chain


def get_model_info(model_name: str) -> dict[str, Any]:
    """
    Gibt Informationen über ein Modell zurück (z.B. Größe, Parameter, etc.).
    Kann später erweitert werden.
    """
    # Hier könnte man eine externe Datenbank oder API abfragen
    return {
        "name": model_name,
        "normalized": normalize_model_name(model_name),
        "canonical": resolve_alias(model_name),
        "is_valid": model_name in get_available_whisper_models(),
    }


class ModelManager:
    """Singleton‑artige, thread‑sichere Verwaltung aller Whisper‑Modelle mit normalisierten Namen."""

    _instance: ModelManager | None = None
    _lock = threading.Lock()

    def __new__(cls) -> ModelManager:
        with cls._lock:
            if cls._instance is None:
                cls._instance = super().__new__(cls)
                cls._instance._initialized = False
            return cls._instance

    def __init__(self) -> None:
        if self._initialized:
            return
        self._initialized = True
        self._available_models_cache: set[str] | None = None
        self._cache_time: float = 0.0
        self._cache_ttl: float = 300.0
        self._cache_lock = threading.RLock()
        self._aliases: dict[str, str] = {
            normalize_model_name(alias): normalize_model_name(canonical)
            for alias, canonical in MODEL_ALIASES.items()
        }
        self._fallback_chain: list[str] = [
            normalize_model_name(model) for model in DEFAULT_FALLBACK_CHAIN.copy()
        ]

    def normalize(self, name: str) -> str:
        """Normalisiert einen Modellnamen (alle Bindestrich‑Varianten, Whitespace, Lowercase)."""
        return normalize_model_name(name)

    def resolve_alias(self, name: str) -> str:
        """Löst einen Alias auf den kanonischen Namen auf (beide normalisiert)."""
        normalized = self.normalize(name)
        return self._aliases.get(normalized, normalized)

    def get_available_models(self, force_refresh: bool = False) -> set[str]:
        """Gibt die Menge der tatsächlich verfügbaren Modelle zurück (normalisiert, mit Caching)."""
        return get_available_whisper_models(force_refresh)

    def is_valid(self, name: str) -> bool:
        """Prüft, ob der (normalisierte) Modellname in der verfügbaren Liste enthalten ist."""
        canonical = self.resolve_alias(name)
        return canonical in self.get_available_models()

    def get_valid(
        self,
        name: str,
        fallback: str | None = None,
        fallback_chain: list[str] | None = None,
    ) -> str:
        """Liefert einen gültigen Modellnamen – mit Fallback‑Kette (alle normalisiert)."""
        if fallback_chain is not None:
            fallback_chain = [self.normalize(m) for m in fallback_chain]
        return get_valid_model(
            name,
            fallback,
            fallback_chain or self._fallback_chain,
            use_dynamic_list=True,
        )

    def add_alias(self, alias: str, canonical: str) -> None:
        """Fügt einen benutzerdefinierten Alias hinzu (beide werden normalisiert)."""
        key = self.normalize(alias)
        value = self.normalize(canonical)
        self._aliases[key] = value

    def set_fallback_chain(self, chain: list[str]) -> None:
        """Setzt die globale Fallback‑Kette neu (alle Einträge werden normalisiert)."""
        self._fallback_chain = [self.normalize(m) for m in chain]

    def get_fallback_chain(self) -> list[str]:
        """Gibt eine Kopie der aktuellen Fallback‑Kette zurück (normalisiert)."""
        return self._fallback_chain.copy()

    def get_info(self, name: str) -> dict[str, Any]:
        """Gibt Metadaten zu einem Modell zurück (z. B. für Debug‑Zwecke)."""
        return get_model_info(name)

    def clear_cache(self) -> None:
        """Leert den internen Cache der verfügbaren Modelle."""
        with self._cache_lock:
            self._available_models_cache = None
            self._cache_time = 0.0


_model_manager: ModelManager | None = None


def get_model_manager() -> ModelManager:
    """Liefert die zentrale, threadsichere Modell‑Manager‑Instanz."""
    global _model_manager
    if _model_manager is None:
        _model_manager = ModelManager()
    return _model_manager


