class ConfigDefaults:
    """Zentrale Konfigurationskonstanten für Dragon Whisperer.

    Alle Werte sind als Klassenattribute (`ClassVar`) deklariert, damit sie
    von abgeleiteten Klassen überschrieben werden können.
    """

    SAMPLE_RATE: ClassVar[int] = 16000
    """Audio‑Samplerate in Hz (16 kHz optimal für Whisper)."""

    CHANNELS: ClassVar[int] = 1
    """Anzahl der Audiokanäle (1 = Mono, 2 = Stereo). Mono reicht für Whisper aus."""

    AUDIO_FORMAT: ClassVar[str] = "s16le"
    """Rohaudio‑Format (s16le = signed 16‑bit little‑endian)."""

    BYTES_PER_SAMPLE: ClassVar[int] = 2
    """Bytes pro Sample (bei 16‑bit = 2)."""

    DEFAULT_BEAM_SIZE: ClassVar[int] = 10
    """Standard‑Beam‑Size für Whisper‑Decodierung (höher = genauer, aber langsamer)."""

    DEFAULT_TEMPERATURE: ClassVar[float] = 0.0
    """Temperatur für Whisper (0.0 = deterministisch, >0 = zufälliger)."""

    MAX_MEMORY_USAGE: ClassVar[int] = 8 * 1024 * 1024 * 1024
    """Maximaler Arbeitsspeicher in Bytes (8 GB). Wird durch psutil überschrieben, falls verfügbar."""

    MAX_GUI_UPDATES_PER_SECOND: ClassVar[int] = 120
    """Maximale GUI‑Updates pro Sekunde (begrenzt die Auslastung des Hauptthreads)."""

    MAX_CACHE_SIZE: ClassVar[int] = 500
    """Maximale Anzahl Einträge im generischen Cache (LRU)."""

    MAX_TEXT_LINES: ClassVar[int] = 2000
    """Maximale Zeilen in den Text‑Widgets (verhindert Speicherüberlauf)."""

    ENABLE_VAD_FILTER: ClassVar[bool] = True
    """Voice Activity Detection standardmässig aktivieren (entfernt Stille vor Transkription)."""

    VAD_THRESHOLD: ClassVar[float] = 0.25
    """VAD‑Schwellwert (0.0‑1.0, höher = weniger empfindlich)."""

    VAD_MIN_SPEECH_DURATION_MS: ClassVar[int] = 225
    """Minimale Sprachdauer in Millisekunden (kürzere Passagen werden ignoriert)."""

    VAD_MIN_SILENCE_DURATION_MS: ClassVar[int] = 80
    """Minimale Stilledauer in Millisekunden, um einen Satz zu beenden."""

    LANGUAGE_VAD: ClassVar[dict[str, dict[str, Any]]] = {
        "ja": {"threshold": 0.3, "min_speech_ms": 300, "min_silence_ms": 100},
        "ko": {"threshold": 0.3, "min_speech_ms": 300, "min_silence_ms": 100},
        "zh": {"threshold": 0.3, "min_speech_ms": 300, "min_silence_ms": 100},
        "th": {"threshold": 0.3, "min_speech_ms": 300, "min_silence_ms": 100},
        "vi": {"threshold": 0.3, "min_speech_ms": 250, "min_silence_ms": 90},
        "ar": {"threshold": 0.35, "min_speech_ms": 280, "min_silence_ms": 100},
        "ru": {"threshold": 0.3, "min_speech_ms": 240, "min_silence_ms": 80},
        "hi": {"threshold": 0.32, "min_speech_ms": 280, "min_silence_ms": 110},
        "tr": {"threshold": 0.32, "min_speech_ms": 260, "min_silence_ms": 95},
        "fa": {"threshold": 0.33, "min_speech_ms": 270, "min_silence_ms": 100},
    }
    """Sprachspezifische VAD‑Parameter (überschreiben die globalen Werte für bestimmte Sprachen)."""

    BASE_CHUNK_DURATION: ClassVar[int] = 20
    """Standard‑Chunk‑Dauer in Sekunden (20 s ist ein guter Kompromiss)."""

    MIN_CHUNK_DURATION: ClassVar[int] = 2
    """Minimale Chunk‑Dauer (kürzer = niedrigere Latenz, aber weniger Kontext)."""

    MAX_CHUNK_DURATION: ClassVar[int] = 30
    """Maximale Chunk‑Dauer (länger = mehr Kontext, aber höhere Latenz)."""

    CHUNK_OVERLAP: ClassVar[float] = 2.0
    """Überlappung zwischen aufeinanderfolgenden Chunks in Sekunden (verhindert Informationsverlust an den Grenzen)."""

    ADAPTIVE_CHUNK_MIN_SAMPLES: ClassVar[int] = 5
    """Minimale Anzahl von Samples für die adaptive Chunk‑Anpassung."""

    ADAPTIVE_CHUNK_SMOOTHING_ALPHA: ClassVar[float] = 0.3
    """Glättungsfaktor für die adaptive Chunk‑Anpassung (0.0‑1.0)."""

    ADAPTIVE_CHUNK_STABLE_THRESHOLD: ClassVar[int] = 2
    """Anzahl der stabilen Messungen, bevor die Chunk‑Dauer geändert wird."""

    STREAM_TIMEOUT: ClassVar[int] = 25
    """Timeout für Stream‑Verbindungen in Sekunden."""

    INITIAL_BUFFER_SECONDS: ClassVar[float] = 2.0
    """Initiale Puffergrösse in Sekunden (erlaubt einen flüssigen Start)."""

    MAX_EMPTY_READS: ClassVar[int] = 30
    """Maximale Anzahl aufeinanderfolgender leerer Leseversuche, bevor ein Reconnect ausgelöst wird."""

    RECONNECT_DELAY: ClassVar[int] = 2
    """Verzögerung vor einem Reconnect‑Versuch in Sekunden."""

    READ_RETRY_DELAY: ClassVar[float] = 0.1
    """Verzögerung zwischen Leseversuchen bei Timeout in Sekunden."""

    YOUTUBE_TIMEOUT: ClassVar[int] = 60_000_000
    """YouTube‑spezifisches Timeout in Mikrosekunden (60 Sekunden)."""

    NORMAL_TIMEOUT: ClassVar[int] = 90_000_000
    """Normales Timeout für andere Streams in Mikrosekunden (90 Sekunden)."""

    MAX_STREAM_RECONNECTS: ClassVar[int] = 5
    """Maximale Anzahl von Reconnect‑Versuchen pro Stream."""

    STREAM_RECONNECT_DELAY: ClassVar[int] = 2
    """Basisverzögerung zwischen Reconnects in Sekunden."""

    STREAM_RECONNECT_BACKOFF_FACTOR: ClassVar[float] = 2.0
    """Exponentieller Backoff‑Faktor für Reconnects."""

    READ_EMPTY_SLEEP_BASE: ClassVar[float] = 0.1
    """Basis‑Schlafzeit bei leeren Lesevorgängen."""

    READ_ERROR_BACKOFF_BASE: ClassVar[float] = 0.1
    """Basis‑Backoff bei Lese‑Fehlern."""

    YOUTUBE_IDLE_TIMEOUT: ClassVar[int] = 25
    """Inaktivitäts‑Timeout für YouTube‑Streams in Sekunden."""

    YOUTUBE_INITIAL_TIMEOUT: ClassVar[int] = 25
    """Initiales Timeout für YouTube‑Verbindungen."""

    YOUTUBE_URL_REFRESH_INTERVAL: ClassVar[int] = 600
    """Intervall für das Aktualisieren der YouTube‑Audio‑URL in Sekunden (10 Minuten)."""

    YOUTUBE_URL_REFRESH_MAX_ATTEMPTS: ClassVar[int] = 3
    """Maximale Versuche, eine frische YouTube‑URL zu holen."""

    YOUTUBE_LOW_QUALITY_MAX_CHUNKS: ClassVar[int] = 5
    """Anzahl der Chunks mit niedriger Qualität, bevor ein Fallback ausgelöst wird."""

    YOUTUBE_INITIAL_WAIT: ClassVar[float] = 3.0
    """Wartezeit nach dem Start eines YouTube‑Streams in Sekunden."""

    FFMPEG_START_WAIT: ClassVar[float] = 1.5
    """Wartezeit nach dem Start von FFmpeg, bevor mit dem Lesen begonnen wird."""

    STREAM_TEST_TIMEOUT: ClassVar[int] = 8
    """Timeout für den initialen Stream‑Test in Sekunden."""

    YOUTUBE_STREAM_TEST_TIMEOUT: ClassVar[int] = 8
    """YouTube‑spezifischer Stream‑Test‑Timeout."""

    READ_WITH_TIMEOUT_SELECT_INTERVAL: ClassVar[float] = 0.001
    """Intervall für select() bei Lesevorgängen mit Timeout."""

    READ_WITH_TIMEOUT_EMPTY_LOG_INTERVAL: ClassVar[int] = 10
    """Log‑Intervall für leere Lesevorgänge (Anzahl der Versuche)."""

    MAX_BACKOFF: ClassVar[int] = 30
    """Maximale Backoff‑Zeit in Sekunden."""

    BUFFER_FLUSH_INACTIVITY: ClassVar[float] = 10.0
    """Inaktivitätszeit, nach der der Puffer geleert wird, in Sekunden."""

    BUFFER_FLUSH_TIMEOUT: ClassVar[float] = 30.0
    """Timeout für Puffer‑Leerung in Sekunden."""

    PROGRESS_UPDATE_INTERVAL: ClassVar[float] = 0.5
    """Intervall für Fortschritts‑Updates in Sekunden."""

    ERRORS_BEFORE_CHUNK_REDUCTION: ClassVar[int] = 3
    """Anzahl der Fehler, bevor die Chunk‑Dauer reduziert wird."""

    SUCCESSES_BEFORE_CHUNK_INCREASE: ClassVar[int] = 5
    """Anzahl der Erfolge, bevor die Chunk‑Dauer erhöht wird."""

    FFMPEG_BUFSIZE: ClassVar[str] = "2048k"
    """FFmpeg Puffergrösse (2 MB)."""

    FFMPEG_THREADS: ClassVar[int] = 1
    """Anzahl der FFmpeg‑Threads (1 = automatisch)."""

    FFMPEG_PROBESIZE: ClassVar[str] = "32"
    """FFmpeg Probesize in MB (kleiner Wert für schnellere Initialisierung)."""

    FFMPEG_ANALYZE_DURATION: ClassVar[str] = "0"
    """FFmpeg Analyze‑Duration (0 = automatisch)."""

    AUDIO_ENHANCEMENT_ENABLED: ClassVar[bool] = True
    """Audio‑Enhancement standardmässig aktivieren."""

    MIN_RMS_THRESHOLD: ClassVar[float] = 0.002
    """Minimaler RMS‑Wert, ab dem eine Verstärkung angewendet wird."""

    TARGET_RMS: ClassVar[float] = 0.2
    """Ziel‑RMS‑Wert für die automatische Verstärkung."""

    MAX_GAIN: ClassVar[float] = 5.0
    """Maximaler Verstärkungsfaktor."""

    CLIPPING_THRESHOLD: ClassVar[float] = 0.9
    """Schwellwert für Clipping‑Erkennung (0.9 = 90 % des Maximalwerts)."""

    NOISEREDUCE_INTERVAL: ClassVar[int] = 10
    """Intervall (Anzahl der Chunks) für die Anwendung von noisereduce."""

    NOISEREDUCE_MIN_LENGTH: ClassVar[int] = 32000
    """Minimale Audio‑Länge in Samples für noisereduce (2 Sekunden bei 16 kHz)."""

    AUDIO_ENHANCEMENT_MIN_LENGTH: ClassVar[int] = 1600
    """Minimale Audio‑Länge für Enhancement in Bytes."""

    LOW_QUALITY_CHUNK_THRESHOLD_FACTOR: ClassVar[float] = 0.15
    """Faktor für die Erkennung niedriger Qualität (im Verhältnis zur erwarteten Dauer)."""

    LOW_QUALITY_CHUNK_LOG_LEVEL: ClassVar[int] = 4
    """Log‑Level für Low‑Quality‑Warnungen."""

    LOW_QUALITY_CHUNK_LOG_INTERVAL: ClassVar[int] = 10
    """Intervall für Low‑Quality‑Logs (Anzahl der Chunks)."""

    DUPLICATE_CHECK_ENABLED: ClassVar[bool] = False
    """Duplikaterkennung standardmässig deaktiviert (spart CPU)."""

    RECENT_TRANSCRIPTIONS_SIZE: ClassVar[int] = 10
    """Anzahl der letzten Transkriptionen, die für die Duplikatprüfung gespeichert werden."""

    MIN_TEXT_LENGTH: ClassVar[int] = 3
    """Minimale Textlänge für die Duplikatprüfung (kürzere Texte werden ignoriert)."""

    MIN_UNIQUE_WORDS_RATIO: ClassVar[float] = 0.3
    """Minimaler Anteil einzigartiger Wörter (verhindert Wiederholungen wie 'ja ja ja')."""

    SUBTITLE_BUFFER_SIZE: ClassVar[int] = 1000
    """Maximale Anzahl von Untertitel‑Segmenten im Puffer."""

    ENABLE_TIMED_TRANSCRIPTIONS: ClassVar[bool] = True
    """Zeitstempel für Transkriptionen aktivieren (für Untertitel‑Modus)."""

    ENABLE_TIMED_TRANSLATIONS: ClassVar[bool] = True
    """Zeitstempel für Übersetzungen aktivieren (für Untertitel‑Modus)."""

    ENABLE_DEBUG_LOGGING: ClassVar[bool] = True
    """Debug‑Logging global aktivieren."""

    LOG_CHUNK_PROCESSING: ClassVar[bool] = False
    """Detailliertes Logging für Chunk‑Verarbeitung (sehr ausführlich)."""

    LOG_AUDIO_STATS: ClassVar[bool] = True
    """Audio‑Statistiken (RMS, Verstärkung) loggen."""

    LOG_PERFORMANCE: ClassVar[bool] = True
    """Performance‑Metriken (Verarbeitungszeit, Realtime‑Faktor) loggen."""

    LOG_STREAM_EVENTS: ClassVar[bool] = True
    """Stream‑Ereignisse (Verbindung, Timeout, Reconnect) loggen."""

    PERFORMANCE_LOG_INTERVAL: ClassVar[int] = 50
    """Intervall für Performance‑Logs (Anzahl der Chunks)."""

    MAX_CACHE_SIZE_MB: ClassVar[int] = 200
    """Maximale Cache‑Grösse in MB (erhöht von 100 MB auf 200 MB)."""

    CACHE_ENABLED: ClassVar[bool] = True
    """Caching global aktivieren."""

    TRANSCRIPTION_CACHE_SIZE: ClassVar[int] = 1000
    """Maximale Anzahl Einträge im Transkriptions‑Cache (erhöht von 500 auf 1000)."""

    TRANSCRIPTION_CACHE_TTL: ClassVar[int] = 600
    """Lebensdauer von Transkriptions‑Cache‑Einträgen in Sekunden (erhöht von 300 s auf 600 s)."""

    TRANSLATION_CACHE_SIZE: ClassVar[int] = 2000
    """Maximale Anzahl Einträge im Übersetzungs‑Cache (erhöht von 1000 auf 2000)."""

    TRANSLATION_CACHE_TTL: ClassVar[int] = 7200
    """Lebensdauer von Übersetzungs‑Cache‑Einträgen in Sekunden (erhöht von 3600 s auf 7200 s)."""

    AUDIO_CACHE_SIZE: ClassVar[int] = 512
    """Maximale Anzahl Einträge im Audio‑Cache (erhöht von 256 auf 512)."""

    AUDIO_CACHE_TTL: ClassVar[int] = 3600
    """Lebensdauer von Audio‑Cache‑Einträgen in Sekunden (erhöht von 1800 s auf 3600 s)."""

    MAX_CONSECUTIVE_ERRORS: ClassVar[int] = 5
    """Maximale aufeinanderfolgende Fehler, bevor der Stream neu gestartet wird."""

    ALLOWED_FILE_SCHEME_PREFIX: ClassVar[str] = "file://"
    """Präfix für lokale Dateien."""

    ALLOWED_FILE_BASE_DIRS: ClassVar[list[str]] = [
        str(Path.home().resolve()),
        os.getcwd(),
    ]
    """Standardmässig erlaubte Basisverzeichnisse für Dateizugriff (Home, CWD)."""

    URL_ALLOWED_CHARS: ClassVar[str] = r"a-zA-Z0-9\-._~:/?#\[\]@!$&'()*+,;=%"
    """Erlaubte Zeichen in URLs (RFC 3986‑konform)."""

    YOUTUBE_HEADERS: ClassVar[dict[str, str]] = {
        "User‑Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/134.0.0.0 Safari/537.36",
        "Referer": "https://www.youtube.com/",
        "Origin": "https://www.youtube.com",
        "Accept": "*/*",
        "Accept‑Language": "en‑US,en;q=0.9",
    }
    """HTTP‑Header für YouTube‑Anfragen (umgeht Blockaden)."""

    PLATFORM_CONFIG: ClassVar[dict[str, dict[str, Any]]] = {
        "windows": {
            "ffmpeg_flags": ["‑reconnect", "1", "‑reconnect_streamed", "1"],
            "process_creation_flags": 0x08000000,
        },
        "macos": {
            "ffmpeg_flags": ["‑reconnect", "1", "‑reconnect_on_network_error", "1"],
            "start_new_session": True,
        },
        "linux": {
            "ffmpeg_flags": ["‑reconnect", "1", "‑reconnect_streamed", "1"],
            "start_new_session": True,
        },
    }
    """Plattformspezifische FFmpeg‑ und Prozess‑Parameter."""

    GUI_QUEUE_MAX_SIZE: ClassVar[int] = 200
    """Maximale Größe der GUI‑Queue (begrenzt die GUI‑Last)."""

    GUI_QUEUE_CLEANUP_TARGET: ClassVar[int] = 100
    """Zielgröße der GUI‑Queue nach einer Bereinigung."""

    TEXT_QUEUE_MAX_SIZE: ClassVar[int] = 150
    """Maximale Größe der Text‑Queue (Transkriptionen/Übersetzungen)."""

    TEXT_QUEUE_CLEANUP_TARGET: ClassVar[int] = 75
    """Zielgröße der Text‑Queue nach einer Bereinigung."""

    WHISPER_MODELS: ClassVar[list[str]] = [
        "tiny",
        "tiny.en",
        "base",
        "base.en",
        "small",
        "small.en",
        "medium",
        "large-v2",
        "large-v3",
        "large-v3-turbo",
        "turbo",
        "distil-large-v3",
    ]
    """Liste aller von Whisper unterstützten Modelle (für ComboBox und Validierung)."""

    MAX_REFRESH_ATTEMPTS: ClassVar[int] = 3
    """Maximale Anzahl von Refresh‑Versuchen für Stream‑URLs."""

    REFRESH_RETRY_DELAY_BASE: ClassVar[float] = 2.0
    """Basisverzögerung für Refresh‑Wiederholungen in Sekunden."""

    REFRESH_RETRY_DELAY_MAX: ClassVar[float] = 10.0
    """Maximale Verzögerung für Refresh‑Wiederholungen."""

    STALLED_RECONNECT_LOG_INTERVAL: ClassVar[float] = 10.0
    """Intervall für Logs bei hängenden Reconnects in Sekunden."""

    @classmethod
    def print_debug_info(cls) -> None:
        """Gibt eine Übersicht aller Konfigurationswerte für Debugging‑Zwecke aus."""
        logger.debug("=" * 60)
        logger.debug("ConfigDefaults Debug Information")
        logger.debug("=" * 60)
        for name, value in cls.__dict__.items():
            if not name.startswith("_") and not callable(value):
                if isinstance(value, (list, dict)) and len(str(value)) > 100:
                    value_str = str(value)[:100] + "..."
                else:
                    value_str = str(value)
                logger.debug(f"  {name:35} = {value_str}")
        logger.debug("=" * 60)

    @classmethod
    def validate_constants(cls) -> list[str]:
        """Validiert die Konstanten auf Konsistenz und gibt eine Liste von Problemen zurück."""
        issues = []

        # Audio‑Parameter
        if cls.SAMPLE_RATE not in (8000, 16000, 22050, 44100, 48000):
            issues.append(
                f"SAMPLE_RATE={cls.SAMPLE_RATE} (erwartet: 8000,16000,22050,44100,48000)"
            )
        if cls.CHANNELS not in (1, 2):
            issues.append(f"CHANNELS={cls.CHANNELS} (erwartet: 1 oder 2)")

        # Chunk‑Parameter
        if cls.MIN_CHUNK_DURATION >= cls.MAX_CHUNK_DURATION:
            issues.append(
                f"MIN_CHUNK_DURATION={cls.MIN_CHUNK_DURATION} >= MAX_CHUNK_DURATION={cls.MAX_CHUNK_DURATION}"
            )
        if (
            cls.BASE_CHUNK_DURATION < cls.MIN_CHUNK_DURATION
            or cls.BASE_CHUNK_DURATION > cls.MAX_CHUNK_DURATION
        ):
            issues.append(
                f"BASE_CHUNK_DURATION={cls.BASE_CHUNK_DURATION} außerhalb [{cls.MIN_CHUNK_DURATION}, {cls.MAX_CHUNK_DURATION}]"
            )

        # Timeouts (sinnvolle Bereiche)
        if cls.YOUTUBE_TIMEOUT < 10_000_000:
            issues.append(
                f"YOUTUBE_TIMEOUT={cls.YOUTUBE_TIMEOUT} < 10 s – zu kurz für stabile Verbindungen"
            )
        if cls.NORMAL_TIMEOUT < 20_000_000:
            issues.append(
                f"NORMAL_TIMEOUT={cls.NORMAL_TIMEOUT} < 20 s – zu kurz für stabile Verbindungen"
            )

        if cls.TRANSCRIPTION_CACHE_SIZE < 100:
            issues.append(
                f"TRANSCRIPTION_CACHE_SIZE={cls.TRANSCRIPTION_CACHE_SIZE} < 100 – zu klein für effizientes Caching"
            )
        if cls.TRANSLATION_CACHE_SIZE < 200:
            issues.append(
                f"TRANSLATION_CACHE_SIZE={cls.TRANSLATION_CACHE_SIZE} < 200 – zu klein für effizientes Caching"
            )
        if cls.AUDIO_CACHE_SIZE < 50:
            issues.append(
                f"AUDIO_CACHE_SIZE={cls.AUDIO_CACHE_SIZE} < 50 – zu klein für effizientes Caching"
            )

        if not cls.WHISPER_MODELS:
            issues.append("WHISPER_MODELS ist leer")

        return issues


@dataclass
class Config(ConfigDefaults):
    """Dynamische Konfiguration für Dragon Whisperer.

    Erbt alle Konstanten von `ConfigDefaults`, überschreibt aber einige
    Werte mit dynamischen Standardwerten. Bietet Properties für Chunk‑Grössen,
    Bytes pro Sekunde und Hilfsmethoden für Filter, Timeouts und Plattform‑Konfig.
    """

    _base_chunk_duration: int = ConfigDefaults.BASE_CHUNK_DURATION
    CHUNK_OVERLAP: float = ConfigDefaults.CHUNK_OVERLAP
    MIN_CHUNK_DURATION: int = ConfigDefaults.MIN_CHUNK_DURATION
    MAX_CHUNK_DURATION: int = ConfigDefaults.MAX_CHUNK_DURATION
    LANGUAGE_VAD: dict[str, dict[str, Any]] = field(
        default_factory=ConfigDefaults.LANGUAGE_VAD.copy
    )
    _actual_chunk_duration: float = field(
        init=False, default=float(ConfigDefaults.BASE_CHUNK_DURATION)
    )

    AUDIO_FILTER: str = "aresample=16000"
    LANGUAGE_FILTERS: dict[str, str] = field(
        default_factory=lambda: dict.fromkeys(
            ConfigDefaults.LANGUAGE_VAD, "aresample=16000"
        )
    )
    FILTER_PROFILES: dict[str, str] = field(
        default_factory=lambda: {
            "transcription": "aresample=16000",
            "translation": "aresample=16000",
            "realtime": "aresample=16000",
            "noisy": "aresample=16000,volume=2.5,highpass=f=150,lowpass=f=3000",
            "music": "aresample=16000",
            "podcast": "aresample=16000",
        }
    )

    YOUTUBE_HEADERS: dict[str, str] = field(
        default_factory=ConfigDefaults.YOUTUBE_HEADERS.copy
    )
    PLATFORM_CONFIG: dict[str, dict[str, Any]] = field(
        default_factory=ConfigDefaults.PLATFORM_CONFIG.copy
    )

    AUDIO_ENHANCEMENT_ENABLED: bool = False
    MIN_RMS_THRESHOLD: float = ConfigDefaults.MIN_RMS_THRESHOLD
    TARGET_RMS: float = ConfigDefaults.TARGET_RMS
    MAX_GAIN: float = ConfigDefaults.MAX_GAIN
    CLIPPING_THRESHOLD: float = ConfigDefaults.CLIPPING_THRESHOLD

    DUPLICATE_CHECK_ENABLED: bool = False
    RECENT_TRANSCRIPTIONS_SIZE: int = ConfigDefaults.RECENT_TRANSCRIPTIONS_SIZE
    MIN_TEXT_LENGTH: int = ConfigDefaults.MIN_TEXT_LENGTH
    MIN_UNIQUE_WORDS_RATIO: float = ConfigDefaults.MIN_UNIQUE_WORDS_RATIO

    SUBTITLE_BUFFER_SIZE: int = ConfigDefaults.SUBTITLE_BUFFER_SIZE
    ENABLE_TIMED_TRANSCRIPTIONS: bool = ConfigDefaults.ENABLE_TIMED_TRANSCRIPTIONS
    ENABLE_TIMED_TRANSLATIONS: bool = ConfigDefaults.ENABLE_TIMED_TRANSLATIONS

    ENABLE_DEBUG_LOGGING: bool = ConfigDefaults.ENABLE_DEBUG_LOGGING
    LOG_CHUNK_PROCESSING: bool = ConfigDefaults.LOG_CHUNK_PROCESSING
    LOG_AUDIO_STATS: bool = ConfigDefaults.LOG_AUDIO_STATS
    LOG_PERFORMANCE: bool = ConfigDefaults.LOG_PERFORMANCE
    LOG_STREAM_EVENTS: bool = ConfigDefaults.LOG_STREAM_EVENTS
    PERFORMANCE_LOG_INTERVAL: int = ConfigDefaults.PERFORMANCE_LOG_INTERVAL

    MAX_CACHE_SIZE_MB: int = ConfigDefaults.MAX_CACHE_SIZE_MB
    CACHE_ENABLED: bool = ConfigDefaults.CACHE_ENABLED

    WHISPER_MODELS: list[str] = field(
        default_factory=ConfigDefaults.WHISPER_MODELS.copy
    )

    _cached_bytes_per_second: int | None = field(default=None, init=False, repr=False)

    # ─── Caches für Verfügbarkeitsprüfungen (wiederverwendet) ──────────────
    _scipy_available_cache: ClassVar[bool | None] = None
    _numpy_available_cache: ClassVar[bool | None] = None

    # ─── Properties ──────────────────────────────────────────────────────────

    @property
    def CHUNK_DURATION(self) -> float:
        """Aktuelle Chunk‑Dauer in Sekunden (dynamisch änderbar)."""
        return self._actual_chunk_duration

    @CHUNK_DURATION.setter
    def CHUNK_DURATION(self, value: float) -> None:
        """Setzt die Chunk‑Dauer mit Bereichsprüfung und Logging."""
        old = self._actual_chunk_duration
        # Wert auf gültigen Bereich klemmen und loggen
        if self.MIN_CHUNK_DURATION <= value <= self.MAX_CHUNK_DURATION:
            self._actual_chunk_duration = float(value)
            if abs(old - value) > 0.1 and logger.isEnabledFor(logging.DEBUG):
                _safe_log_debug(f"Chunk-Dauer geändert: {old:.1f}s → {value:.1f}s")
        else:
            clamped = max(self.MIN_CHUNK_DURATION, min(value, self.MAX_CHUNK_DURATION))
            logger.warning(
                f"Chunk-Dauer {value}s außerhalb [{self.MIN_CHUNK_DURATION}, {self.MAX_CHUNK_DURATION}] – "
                f"auf {clamped:.1f}s geklammert",
            )
            self._actual_chunk_duration = clamped

    @property
    def CHUNK_SIZE_BYTES(self) -> int:
        """Grösse eines Audio‑Chunks in Bytes (basierend auf aktueller Chunk‑Dauer)."""
        return int(
            self.CHUNK_DURATION
            * self.SAMPLE_RATE
            * self.CHANNELS
            * self.BYTES_PER_SAMPLE
        )

    @property
    def OVERLAP_SIZE_BYTES(self) -> int:
        """Überlappungsgrösse in Bytes zwischen aufeinanderfolgenden Chunks."""
        return int(
            self.CHUNK_OVERLAP
            * self.SAMPLE_RATE
            * self.CHANNELS
            * self.BYTES_PER_SAMPLE
        )

    @property
    def BYTES_PER_SECOND(self) -> int:
        """Datenrate in Bytes pro Sekunde (mit Caching für Performance)."""
        if self._cached_bytes_per_second is None:
            self._cached_bytes_per_second = (
                self.SAMPLE_RATE * self.CHANNELS * self.BYTES_PER_SAMPLE
            )
            if self.ENABLE_DEBUG_LOGGING and self._get_debug_level() >= 4:
                _safe_log_debug(
                    f"Computed BYTES_PER_SECOND = {self._cached_bytes_per_second} "
                    f"(SR={self.SAMPLE_RATE}, CH={self.CHANNELS}, BPS={self.BYTES_PER_SAMPLE})",
                )
        return self._cached_bytes_per_second

    @property
    def MIN_CHUNK_BYTES(self) -> int:
        """Minimale Chunk‑Grösse in Bytes (entspricht MIN_CHUNK_DURATION)."""
        return int(self.MIN_CHUNK_DURATION * self.BYTES_PER_SECOND)

    @property
    def MAX_CHUNK_BYTES(self) -> int:
        """Maximale Chunk‑Grösse in Bytes (entspricht MAX_CHUNK_DURATION)."""
        return int(self.MAX_CHUNK_DURATION * self.BYTES_PER_SECOND)

    @property
    def INITIAL_BUFFER_BYTES(self) -> int:
        """Grösse des initialen Audiopuffers in Bytes."""
        return int(self.INITIAL_BUFFER_SECONDS * self.BYTES_PER_SECOND)

    # ─── Öffentliche Methoden ────────────────────────────────────────────────

    def get_timeout_microseconds(self, is_youtube: bool = False) -> int:
        """Gibt das passende Timeout in Mikrosekunden zurück."""
        return self.YOUTUBE_TIMEOUT if is_youtube else self.NORMAL_TIMEOUT

    def get_audio_filter(
        self, language: str | None = None, profile: str | None = None
    ) -> str:
        """Gibt einen optimierten Audiofilter basierend auf Sprache und Profil zurück."""
        filter_str = self.AUDIO_FILTER
        if profile and profile in self.FILTER_PROFILES:
            filter_str = self.FILTER_PROFILES[profile]
        if language and language in self.LANGUAGE_FILTERS:
            filter_str = self.LANGUAGE_FILTERS[language]
        if self.LOG_AUDIO_STATS and self._get_debug_level() >= 2:
            _safe_log_debug(
                f"Verwende Audiofilter: {filter_str} (profil={profile}, lang={language})"
            )
        return filter_str

    def get_youtube_headers(self, is_manifest: bool = False) -> dict[str, str]:
        """Gibt die HTTP‑Header für YouTube‑Anfragen zurück."""
        headers = self.YOUTUBE_HEADERS.copy()
        if is_manifest:
            headers.update(
                {"X‑Client‑Data": "CI22yQE=", "Content‑Type": "application/x‑mpegURL"}
            )
        return headers

    def get_platform_config(self, platform: str | None = None) -> dict[str, Any]:
        """Gibt plattformspezifische Konfiguration für FFmpeg und Prozesse zurück."""
        if not platform:
            platform = self._get_system()
        config = self.PLATFORM_CONFIG.get(platform, self.PLATFORM_CONFIG["linux"])
        if self.ENABLE_DEBUG_LOGGING and self._get_debug_level() >= 3:
            _safe_log_debug(f"Plattform‑Konfiguration für {platform}: {config}")
        return config

    # ─── Interne Hilfsmethoden ──────────────────────────────────────────────

    @classmethod
    def _get_debug_level(cls) -> int:
        """Hilfsmethode, um den globalen DEBUG_LEVEL sicher zu lesen."""
        try:
            return globals().get("DEBUG_LEVEL", 0)
        except Exception:
            return 0

    @classmethod
    def _get_system(cls) -> str:
        """Hilfsmethode, um das Betriebssystem sicher zu lesen."""
        try:
            return globals().get("SYSTEM", "linux").lower()
        except Exception:
            return "linux"

    @classmethod
    def _is_scipy_available(cls) -> bool:
        """Prüft, ob scipy verfügbar ist (mit Caching und spezifischem Exception‑Handling)."""
        if cls._scipy_available_cache is not None:
            return cls._scipy_available_cache
        try:
            result = importlib.util.find_spec("scipy") is not None
        except (ImportError, ModuleNotFoundError):
            result = False
        except Exception as e:
            logger.debug("Unerwarteter Fehler bei scipy‑Prüfung: %s", e, exc_info=True)
            result = False
        cls._scipy_available_cache = result
        return result

    @classmethod
    def _is_numpy_available(cls) -> bool:
        """Prüft, ob numpy verfügbar ist (mit Caching)."""
        if cls._numpy_available_cache is not None:
            return cls._numpy_available_cache
        try:
            result = importlib.util.find_spec("numpy") is not None
        except (ImportError, ModuleNotFoundError):
            result = False
        except Exception as e:
            logger.debug("Unerwarteter Fehler bei numpy‑Prüfung: %s", e, exc_info=True)
            result = False
        cls._numpy_available_cache = result
        return result

    # ─── __setattr__ und __post_init__ ──────────────────────────────────────

    def __setattr__(self, name: str, value: Any) -> None:
        """Invalidiert den BYTES_PER_SECOND‑Cache nur bei tatsächlicher Wertänderung."""
        if name in ("SAMPLE_RATE", "CHANNELS", "BYTES_PER_SAMPLE"):
            current = getattr(self, name, None)
            if current != value:
                object.__setattr__(self, "_cached_bytes_per_second", None)
                if self.ENABLE_DEBUG_LOGGING and self._get_debug_level() >= 4:
                    _safe_log_debug(
                        f"Invalidated BYTES_PER_SECOND cache due to change of {name} "
                        f"({current} → {value})",
                    )
        super().__setattr__(name, value)

    def __post_init__(self) -> None:
        """Initialisiert die Config‑Instanz nach der Dataclass‑Erstellung."""
        self._actual_chunk_duration = float(self._base_chunk_duration)
        self._cached_bytes_per_second = (
            self.SAMPLE_RATE * self.CHANNELS * self.BYTES_PER_SAMPLE
        )

        # ★ Erweiterte Validierung und Reparatur ★
        self._validate_and_repair()
        self._log_initialization()
        self._warn_missing_dependencies()

    def _validate_and_repair(self) -> None:
        """Führt Validierung und automatische Reparatur durch – jetzt robuster."""
        if self.validate_config():
            return

        logger.warning(
            "Config‑Instanz enthält ungültige Werte. Versuche automatische Korrektur."
        )

        # Chunk‑Dauer korrigieren
        if self.CHUNK_DURATION < self.MIN_CHUNK_DURATION:
            logger.warning(
                f"CHUNK_DURATION={self.CHUNK_DURATION:.1f}s < MIN_CHUNK_DURATION={self.MIN_CHUNK_DURATION}s. "
                f"Setze auf MIN_CHUNK_DURATION.",
            )
            self.CHUNK_DURATION = self.MIN_CHUNK_DURATION
        elif self.CHUNK_DURATION > self.MAX_CHUNK_DURATION:
            logger.warning(
                f"CHUNK_DURATION={self.CHUNK_DURATION:.1f}s > MAX_CHUNK_DURATION={self.MAX_CHUNK_DURATION}s. "
                f"Setze auf MAX_CHUNK_DURATION.",
            )
            self.CHUNK_DURATION = self.MAX_CHUNK_DURATION

        # Overlap korrigieren (darf nicht grösser als Chunk sein)
        if self.CHUNK_OVERLAP >= self.CHUNK_DURATION:
            new_overlap = max(0.0, self.CHUNK_DURATION * 0.1)
            logger.warning(
                f"CHUNK_OVERLAP={self.CHUNK_OVERLAP:.1f}s >= CHUNK_DURATION={self.CHUNK_DURATION:.1f}s. "
                f"Setze auf {new_overlap:.1f}s.",
            )
            self.CHUNK_OVERLAP = new_overlap

        # Sample‑Rate korrigieren (Whisper erwartet 16000 Hz)
        if self.SAMPLE_RATE not in (8000, 16000, 22050, 44100, 48000):
            logger.warning(
                f"SAMPLE_RATE={self.SAMPLE_RATE}Hz ist unüblich. "
                f"Whisper erwartet 16000Hz. Setze auf 16000Hz.",
            )
            self.SAMPLE_RATE = 16000

        # Kanäle korrigieren
        if self.CHANNELS not in (1, 2):
            logger.warning(
                f"CHANNELS={self.CHANNELS} ist ungültig. Setze auf 1 (Mono)."
            )
            self.CHANNELS = 1

        # Cache neu berechnen
        self._cached_bytes_per_second = (
            self.SAMPLE_RATE * self.CHANNELS * self.BYTES_PER_SAMPLE
        )

    def _log_initialization(self) -> None:
        """Protokolliert die Initialisierungsdetails (abhängig vom Debug‑Level)."""
        if not self.ENABLE_DEBUG_LOGGING:
            return

        level = self._get_debug_level()
        if level >= 2:
            _safe_log_debug(
                f"Config initialisiert: chunk={self.CHUNK_DURATION:.1f}s "
                f"({self.CHUNK_SIZE_BYTES:,} bytes), "
                f"sample_rate={self.SAMPLE_RATE}Hz, channels={self.CHANNELS}, "
                f"overlap={self.CHUNK_OVERLAP:.1f}s ({self.OVERLAP_SIZE_BYTES:,} bytes), "
                f"bytes_per_sec={self.BYTES_PER_SECOND:,}",
            )
        elif level >= 1:
            _safe_log_debug(
                f"Config: chunk={self.CHUNK_DURATION:.1f}s, "
                f"sr={self.SAMPLE_RATE}Hz, ch={self.CHANNELS}",
            )

        # Einmalige Validierung der Konstanten (nur beim ersten Mal)
        if not getattr(Config, "_constants_validated", False):
            issues = Config.validate_constants()
            if issues:
                logger.error(
                    f"❌ ConfigDefaults enthält inkonsistente Konstanten: {', '.join(issues)}"
                )
                if level >= 3:
                    _safe_log_debug(f"Validation issues details: {issues}")
            elif level >= 2:
                _safe_log_debug("✅ ConfigDefaults validation passed")
            Config._constants_validated = True

    def _warn_missing_dependencies(self) -> None:
        """Warnt bei fehlenden optionalen Abhängigkeiten."""
        if self.AUDIO_ENHANCEMENT_ENABLED and not self._is_scipy_available():
            logger.warning(
                "Audio‑Enhancement ist aktiviert, aber scipy ist nicht installiert. "
                "Rauschunterdrückung wird nicht funktionieren.",
            )
        if self.DUPLICATE_CHECK_ENABLED and not (
            self._is_scipy_available() or self._is_numpy_available()
        ):
            logger.warning(
                "Duplikatprüfung ist aktiviert, aber weder scipy noch numpy sind verfügbar. "
                "Die Ähnlichkeitsberechnung wird langsam sein.",
            )

    def calculate_optimal_chunk_duration(
        self,
        model_size: str = "medium",
        is_realtime: bool = False,
        device: str | None = None,
        compute_type: str | None = None,
        use_dynamic: bool = True,
    ) -> float:
        """Berechnet die optimale Chunk‑Dauer basierend auf Modell, Hardware und Echtzeit‑Anforderung."""
        # Echtzeit‑Modus
        if is_realtime:
            min_dur = float(self.MIN_CHUNK_DURATION)
            duration = (
                min(8.0, min_dur * 1.5)
                if (device == "cuda" and use_dynamic)
                else min_dur
            )
            if self.ENABLE_DEBUG_LOGGING and self._get_debug_level() >= 3:
                _safe_log_debug(
                    f"Echtzeit‑Modus: Chunk‑Dauer = {duration:.1f}s (device={device})"
                )
            return duration

        # Basis‑Dauer aus Modellgrösse
        model_lower = model_size.lower()
        base_model = model_lower.replace(".en", "")
        model_base = {
            "tiny": 3.0,
            "base": 4.0,
            "small": 5.0,
            "medium": 6.0,
            "large": 7.0,
            "large‑v2": 7.0,
            "large‑v3": 7.0,
            "large‑v3‑turbo": 5.0,
            "distil‑large‑v3": 4.0,
        }
        duration = model_base.get(base_model, 5.0)

        # Dynamische Anpassung
        if use_dynamic:
            compute_factor = {
                "int8": 1.2,
                "float16": 0.9,
                "float32": 0.7,
            }.get(compute_type or "", 1.0)
            duration *= compute_factor

            device_factor = {
                "cuda": 1.3,
                "mps": 1.1,
                "cpu": 0.8,
            }.get(device or "", 1.0)
            duration *= device_factor

        duration = max(self.MIN_CHUNK_DURATION, min(duration, self.MAX_CHUNK_DURATION))
        duration = round(duration * 2) / 2.0

        if self.ENABLE_DEBUG_LOGGING and self._get_debug_level() >= 2:
            _safe_log_debug(
                f"Optimale Chunk‑Dauer für {model_size}: {duration:.1f}s "
                f"(realtime={is_realtime}, device={device}, compute={compute_type})",
            )
        return duration

    @classmethod
    def get_dynamic_max_memory(cls) -> int:
        """Ermittelt dynamisch die maximale Arbeitsspeichergrenze (75 % des verfügbaren RAM)."""
        try:
            import psutil

            mem = psutil.virtual_memory()
            limit = int(mem.total * 0.75)
            if cls._get_debug_level() >= 2:
                _safe_log_debug(
                    f"Dynamisches Speicherlimit: {limit // (1024**2)} MB "
                    f"(75% von {mem.total // (1024**2)} MB)",
                )
            return limit
        except ImportError:
            if cls._get_debug_level() >= 1:
                _safe_log_debug(
                    "psutil nicht verfügbar – verwende Standard‑Speicherlimit"
                )
            return cls.MAX_MEMORY_USAGE
        except AttributeError as e:
            logger.debug("psutil hat nicht das erwartete Attribut: %s", e)
            return cls.MAX_MEMORY_USAGE
        except Exception as e:
            logger.warning("Unerwarteter Fehler in get_dynamic_max_memory: %s", e)
            return cls.MAX_MEMORY_USAGE

    def validate_config(self) -> bool:
        """Validiert die aktuelle Konfiguration auf Konsistenz."""
        try:
            valid = (
                self.SAMPLE_RATE in (8000, 16000, 22050, 44100, 48000)
                and self.CHANNELS in (1, 2)
                and self.MIN_CHUNK_DURATION
                <= self.CHUNK_DURATION
                <= self.MAX_CHUNK_DURATION
                and 0.0 <= self.CHUNK_OVERLAP < self.CHUNK_DURATION
            )
            if not valid and self.ENABLE_DEBUG_LOGGING:
                logger.warning("Config‑Validierung fehlgeschlagen")
            return valid
        except (TypeError, ValueError) as e:
            logger.error(f"Config‑Validierung Ausnahme: {e}")
            return False
        except Exception as e:
            logger.exception(f"Unerwartete Ausnahme in validate_config: {e}")
            return False

    # ─── Zusammenfassung ausgeben ────────────────────────────────────────────

    def print_summary(
        self, verbose: bool = False, return_str: bool = False
    ) -> str | None:
        """Gibt eine übersichtliche Zusammenfassung der wichtigsten Konfigurationswerte aus."""
        lines = []
        lines.append("=" * 60)
        lines.append("🎵 CONFIGURATION SUMMARY")
        lines.append("=" * 60)

        lines.append(
            f"📊 Audio:        {self.SAMPLE_RATE} Hz, {self.CHANNELS} channel(s)"
        )
        lines.append(
            f"📦 Chunk:        {self.CHUNK_DURATION:.1f} s ({self.CHUNK_SIZE_BYTES:,} bytes)"
        )
        if verbose:
            lines.append(
                f"   Overlap:      {self.CHUNK_OVERLAP:.1f} s ({self.OVERLAP_SIZE_BYTES:,} bytes)"
            )
            lines.append(
                f"   Min/Max:      {self.MIN_CHUNK_DURATION:.1f} s / {self.MAX_CHUNK_DURATION:.1f} s"
            )
        lines.append(f"⚡ Bytes/sec:    {self.BYTES_PER_SECOND:,}")
        lines.append(f"🎛️ Filter:       {self.AUDIO_FILTER}")

        if verbose:
            lines.append(
                f"🎚️ Audio Enhancement: {'ON' if self.AUDIO_ENHANCEMENT_ENABLED else 'OFF'}"
            )

        lines.append(f"✅ Valid:         {'YES' if self.validate_config() else 'NO'}")
        lines.append("=" * 60)

        output = "\n".join(lines)
        if return_str:
            return output
        logger.info(output)
        return None

    def reset_to_defaults(self) -> None:
        """Setzt alle dynamischen Werte auf die Standardwerte aus ConfigDefaults zurück."""
        self._base_chunk_duration = ConfigDefaults.BASE_CHUNK_DURATION
        self.CHUNK_OVERLAP = ConfigDefaults.CHUNK_OVERLAP
        self.MIN_CHUNK_DURATION = ConfigDefaults.MIN_CHUNK_DURATION
        self.MAX_CHUNK_DURATION = ConfigDefaults.MAX_CHUNK_DURATION
        self.CHUNK_DURATION = ConfigDefaults.BASE_CHUNK_DURATION
        self.AUDIO_ENHANCEMENT_ENABLED = False
        self.DUPLICATE_CHECK_ENABLED = False
        self.CACHE_ENABLED = ConfigDefaults.CACHE_ENABLED
        if self.ENABLE_DEBUG_LOGGING:
            _safe_log_debug("Config auf Standardwerte zurückgesetzt")

    def get_debug_info(self) -> dict[str, Any]:
        """Sammelt detaillierte Debug‑Informationen über die aktuelle Konfiguration."""
        return {
            "sample_rate": self.SAMPLE_RATE,
            "channels": self.CHANNELS,
            "chunk_duration": self.CHUNK_DURATION,
            "chunk_size_bytes": self.CHUNK_SIZE_BYTES,
            "bytes_per_second": self.BYTES_PER_SECOND,
            "min_chunk_duration": self.MIN_CHUNK_DURATION,
            "max_chunk_duration": self.MAX_CHUNK_DURATION,
            "audio_filter": self.AUDIO_FILTER,
            "audio_enhancement": self.AUDIO_ENHANCEMENT_ENABLED,
            "duplicate_check": self.DUPLICATE_CHECK_ENABLED,
            "cache_enabled": self.CACHE_ENABLED,
            "max_cache_mb": self.MAX_CACHE_SIZE_MB,
            "whisper_models": self.WHISPER_MODELS,
            "vad_threshold": self.VAD_THRESHOLD,
            "valid": self.validate_config(),
        }


