class DummyQueue(queue.Queue):
    """Thread‑sichere Dummy‑Queue, die sich exakt wie `queue.Queue` verhält,
    aber die interne Speicherung über eine einfache Python‑Liste realisiert.
    Sie erbt von `queue.Queue`, überschreibt nur die geschützten Hooks
    und ist dadurch in allen typisierten Kontexten voll kompatibel.
    """

    __slots__ = ()

    def __init__(self, maxsize: int = 0) -> None:
        super().__init__(maxsize)

    def _init(self, maxsize: int) -> None:
        self.queue: list[Any] = []

    def _qsize(self) -> int:
        return len(self.queue)

    def _put(self, item: Any) -> None:
        self.queue.append(item)

    def _get(self) -> Any:
        return self.queue.pop(0)


@dataclass
class TranscriptionResult:
    """Ergebnis einer Transkription mit Text, Konfidenz, Sprache und optionalen Zeitstempeln."""

    text: str
    confidence: float
    language: str = "unknown"
    language_probability: float | None = None
    timestamp: float = field(default_factory=time.time)
    start: float | None = None
    end: float | None = None

    def __post_init__(self) -> None:
        """Validiert und korrigiert die Werte."""
        if not isinstance(self.confidence, (int, float)):
            self.confidence = 0.0
        self.confidence = max(0.0, min(1.0, float(self.confidence)))

        if self.language_probability is not None:
            self.language_probability = max(
                0.0,
                min(1.0, float(self.language_probability)),
            )

        if self.start is not None and self.start < 0.0:
            self.start = 0.0

        if self.end is not None and self.end < 0.0:
            self.end = 0.0

        if self.start is not None and self.end is not None and self.end < self.start:
            self.end = self.start + 0.001

    def to_dict(self) -> dict[str, Any]:
        """Konvertiert das Objekt in ein Dictionary (für JSON‑Export)."""
        return {
            "text": self.text,
            "confidence": self.confidence,
            "language": self.language,
            "language_probability": self.language_probability,
            "timestamp": self.timestamp,
            "start": self.start,
            "end": self.end,
        }

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> TranscriptionResult:
        """Erstellt ein Objekt aus einem Dictionary."""
        return cls(
            text=data.get("text", ""),
            confidence=data.get("confidence", 0.0),
            language=data.get("language", "unknown"),
            language_probability=data.get("language_probability"),
            timestamp=data.get("timestamp", time.time()),
            start=data.get("start"),
            end=data.get("end"),
        )

    def __repr__(self) -> str:
        preview = self.text[:50] + "…" if len(self.text) > 50 else self.text
        return (
            f"TranscriptionResult(text='{preview}', "
            f"conf={self.confidence:.2f}, lang='{self.language}')"
        )


