@dataclass
class StreamInfo:
    """Metadaten eines Streams (YouTube, Twitch, etc.)."""

    title: str
    uploader: str
    duration: str
    view_count: int
    platform: str
    description: str = ""
    duration_seconds: float | None = None
    is_live: bool = False
    thumbnail: str = ""
    original_url: str = ""
    stream_url: str | None = None
    channel_id: str | None = None  # FIXED: Feld ergänzt
    uploader_url: str | None = None  # FIXED: Feld ergänzt

    def __post_init__(self) -> None:
        """Validiert und korrigiert die Werte, berechnet duration_seconds falls möglich."""
        self.view_count = max(self.view_count, 0)

        # Wenn duration_seconds fehlt, aber duration ein String ist, versuche zu parsen
        if self.duration_seconds is None and self.duration and self.duration != "Live":
            try:
                parts = list(map(float, self.duration.split(":")))
                if len(parts) == 3:
                    self.duration_seconds = parts[0] * 3600 + parts[1] * 60 + parts[2]
                elif len(parts) == 2:
                    self.duration_seconds = parts[0] * 60 + parts[1]
                elif len(parts) == 1:
                    self.duration_seconds = parts[0]
            except Exception as e:
                logger.debug("Ignored exception: %s", e, exc_info=True)

        # Kürze Beschreibung auf 500 Zeichen
        if self.description and len(self.description) > 500:
            self.description = self.description[:497] + "..."

        # Plattform normalisieren
        if self.platform:
            self.platform = self.platform.lower()

    def to_dict(self) -> dict[str, Any]:
        """Konvertiert das Objekt in ein Dictionary (für JSON‑Export)."""
        return {
            "title": self.title,
            "uploader": self.uploader,
            "duration": self.duration,
            "view_count": self.view_count,
            "platform": self.platform,
            "description": self.description,
            "duration_seconds": self.duration_seconds,
            "is_live": self.is_live,
            "thumbnail": self.thumbnail,
            "original_url": self.original_url,
            "stream_url": self.stream_url,
            "channel_id": self.channel_id,
            "uploader_url": self.uploader_url,
        }

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> StreamInfo:
        """Erstellt ein Objekt aus einem Dictionary."""
        return cls(
            title=data.get("title", "Unknown Stream"),
            uploader=data.get("uploader", "Unknown"),
            duration=data.get("duration", "Live"),
            view_count=data.get("view_count", 0),
            platform=data.get("platform", "unknown"),
            description=data.get("description", ""),
            duration_seconds=data.get("duration_seconds"),
            is_live=data.get("is_live", False),
            thumbnail=data.get("thumbnail", ""),
            original_url=data.get("original_url", ""),
            stream_url=data.get("stream_url"),
            channel_id=data.get("channel_id"),
            uploader_url=data.get("uploader_url"),
        )

    def __repr__(self) -> str:
        title_preview = self.title[:40] + "…" if len(self.title) > 40 else self.title
        return (
            f"StreamInfo(title='{title_preview}', "
            f"uploader='{self.uploader}', "
            f"duration='{self.duration}', "
            f"platform='{self.platform}')"
        )


