    def _safe_after(
        self,
        delay: int,
        func: Callable,
        *args: Any,
        **kwargs: Any,
    ) -> None:
        """Sicherer `after`-Aufruf, der den Dialog-Zustand prüft."""
        if self._destroyed or not self.dialog.winfo_exists():
            return
        self.dialog.after(delay, func, *args, **kwargs)

    def _is_destroyed(self) -> bool:
        """Gibt zurück, ob der Dialog bereits zerstört wurde."""
        return self._destroyed

    def _set_destroyed(self) -> None:
        """Markiert den Dialog als zerstört."""
        self._destroyed = True

    def _bind_shortcuts(self) -> None:
        """Bindet Tastaturkürzel an den Dialog."""
        self.dialog.bind("<Control-s>", lambda e: self.save_summary())
        self.dialog.bind("<Escape>", lambda e: self.close())

    def _check_ollama_availability(self) -> None:
        """Prüft die Verfügbarkeit von Ollama und zeigt ggf. eine Hilfemeldung an.
        Diese Methode kann jederzeit aufgerufen werden, z.B. nach einem Health-Check.
        """
        # ── 1. Theme sicher holen ─────────────────────────────────────
        try:
            theme = CURRENT_THEME
        except NameError:
            theme = DarkTheme()  # Fallback

        # ── 2. Verfügbarkeit prüfen ──────────────────────────────────
        if self._ollama_available:
            # Status zurücksetzen
            self.status_label.config(text="✅ Ollama verfügbar", fg=theme.SUCCESS)
            # Hilfe-Button entfernen (falls vorhanden)
            if hasattr(self, "_ollama_help_btn") and self._ollama_help_btn is not None:
                try:
                    self._ollama_help_btn.destroy()
                    self._ollama_help_btn = None
                except tk.TclError:
                    pass
            return

        # ── 3. Nicht verfügbar – Status setzen ──────────────────────
        self.status_label.config(
            text="❌ Ollama nicht verfügbar – bitte installieren und starten Sie 'ollama serve'",
            fg=theme.ERROR,
        )

        # ── 4. Hilfe-Button nur einmal hinzufügen ────────────────────
        if not hasattr(self, "_ollama_help_btn") or self._ollama_help_btn is None:
            # Erstelle einen separaten Frame für den Button, um Layout-Konflikte zu vermeiden
            if (
                not hasattr(self, "_ollama_help_frame")
                or self._ollama_help_frame is None
            ):
                self._ollama_help_frame = tk.Frame(self.main, bg=theme.BG_PRIMARY)
                # Bestimme die nächste freie Zeile im main-Frame (grid)
                max_row = 0
                for child in self.main.winfo_children():
                    try:
                        row = int(child.grid_info().get("row", 0))
                        max_row = max(max_row, row)
                    except (tk.TclError, ValueError):
                        pass
                # Füge den Frame in der nächsten Zeile ein
                self._ollama_help_frame.grid(
                    row=max_row + 1, column=0, sticky="ew", pady=5
                )
            else:
                # Stelle sicher, dass der Frame sichtbar ist (falls er ausgeblendet wurde)
                self._ollama_help_frame.grid()

            self._ollama_help_btn = tk.Button(
                self._ollama_help_frame,
                text="📖 Installationshilfe",
                command=self._show_ollama_help,
                bg=getattr(theme, "INFO", "#58a6ff"),
                fg=getattr(theme, "TEXT_PRIMARY", "#e6edf3"),
                cursor="hand2",
                padx=10,
                pady=5,
            )
            self._ollama_help_btn.pack(side="left", padx=5)  # pack im Frame ist erlaubt
        else:
            # Stelle sicher, dass der Button sichtbar ist (falls er ausgeblendet wurde)
            self._ollama_help_btn.pack(side="left", padx=5)

    def _show_ollama_help(self) -> None:
        """Zeigt eine detaillierte Installationsanleitung für Ollama an."""
        help_text = (
            "🐉 **Ollama – Installationsanleitung**\n\n"
            "Ollama wird für die Zusammenfassungsfunktion benötigt.\n\n"
            "📥 **Installation:**\n"
            "• **Windows:**  https://ollama.com/download/windows\n"
            "• **macOS:**    https://ollama.com/download/mac\n"
            "• **Linux:**    curl -fsSL https://ollama.com/install.sh | sh\n\n"
            "▶️ **Starten des Servers:**\n"
            "   Nach der Installation führen Sie im Terminal aus:\n"
            "   `ollama serve`\n\n"
            "📦 **Modell herunterladen (Beispiel):**\n"
            "   `ollama pull llama3.1:8b`\n\n"
            "🔄 **Nach der Installation:**\n"
            "   Schließen Sie diesen Dialog und klicken Sie erneut auf 'Zusammenfassen'.\n"
            "   Die Verbindung wird automatisch hergestellt."
        )
        try:
            DarkMessageBox.showinfo(
                "Ollama – Installationshilfe", help_text, parent=self.dialog, timeout=30
            )
        except Exception as e:
            logger.warning(f"Konnte Hilfedialog nicht öffnen: {e}")
            # Fallback: Status-Label mit Kurzanleitung
            self.status_label.config(
                text="ℹ️ Installieren Sie Ollama von https://ollama.com und starten Sie 'ollama serve'",
                fg=CURRENT_THEME.INFO,
            )

    def _start_ollama_health_check(self) -> None:
        """Startet einen periodischen Health-Check für Ollama (alle 30 Sekunden)."""

        def check():
            if self._destroyed or not self.dialog.winfo_exists():
                return
            # Nur prüfen, wenn kein Summarize läuft (sonst störend)
            if not getattr(self, "_summarize_in_progress", False):
                reachable = False
                try:
                    with self._ollama_usage() as summarizer:
                        reachable = summarizer.is_server_reachable()
                except Exception:
                    pass
                # Verfügbarkeit aktualisieren
                self._ollama_available = reachable
                self._check_ollama_availability()
            self._safe_after(30000, check)  # alle 30 Sekunden

        self._safe_after(30000, check)

