    def _populate_voice_ui(self, voices: list[str]) -> None:
        if not hasattr(self, "_voice_container") or self._voice_container is None:
            return

        container = self._voice_container

        for child in container.winfo_children():
            child.destroy()

        try:
            theme = CURRENT_THEME
        except NameError:
            theme = DarkTheme()

        if not voices:
            tk.Label(
                container,
                text="⚠️ Keine Stimmen gefunden. Bitte später erneut versuchen.",
                bg=theme.BG_SECONDARY,
                fg=theme.WARNING,
                font=Fonts.SMALL,
            ).pack(anchor="w", pady=2)
            return

        try:
            cache_dir = TTSManager.get_piper_cache_dir()
        except Exception:
            cache_dir = ""

        row, col = 0, 0
        self._voice_vars.clear()

        for voice_name in voices[: self.MAX_VOICE_DISPLAY]:
            model_path = (
                os.path.join(cache_dir, f"{voice_name}.onnx") if cache_dir else ""
            )
            json_path = model_path + ".json" if model_path else ""

            fully_installed = (
                os.path.exists(model_path)
                and os.path.getsize(model_path) > 0
                and os.path.exists(json_path)
                and os.path.getsize(json_path) > 0
            )

            display_name = self.PIPER_VOICES.get(
                voice_name,
                voice_name.replace("_", " ").title(),
            )

            if not fully_installed:
                var = tk.BooleanVar(value=False)
                cb = tk.Checkbutton(
                    container,
                    text=display_name,
                    variable=var,
                    bg=theme.BG_SECONDARY,
                    fg=theme.TEXT_PRIMARY,
                    selectcolor=theme.BG_TERTIARY,
                    activebackground=theme.BG_HOVER,
                    anchor="w",
                )
                cb.grid(row=row, column=col, sticky="w", padx=10, pady=2)
                self._voice_vars[voice_name] = var

                if os.path.exists(model_path) and os.path.getsize(model_path) > 0:
                    ToolTip(
                        cb,
                        "✅ Modell vorhanden, aber Konfigurationsdatei fehlt – wird nachgeladen",
                    )
                else:
                    ToolTip(cb, f"Lädt {voice_name} herunter (ca. 50-200 MB)")
            else:
                lbl = tk.Label(
                    container,
                    text=f"✅ {display_name}",
                    bg=theme.BG_SECONDARY,
                    fg=theme.SUCCESS,
                    anchor="w",
                )
                lbl.grid(row=row, column=col, sticky="w", padx=10, pady=2)
                ToolTip(lbl, f"{display_name} ist vollständig installiert")

            col += 1
            if col > 2:
                col = 0
                row += 1

        if len(voices) > self.MAX_VOICE_DISPLAY:
            tk.Label(
                container,
                text=f"… und {len(voices) - self.MAX_VOICE_DISPLAY} weitere Stimmen",
                bg=theme.BG_SECONDARY,
                fg=theme.TEXT_SECONDARY,
                font=Fonts.SMALL,
            ).grid(row=row + 1, column=0, columnspan=3, sticky="w", padx=10, pady=2)

        # Select/Deselect Buttons im Container (unterhalb der Liste)
        select_frame = tk.Frame(container, bg=theme.BG_SECONDARY)
        select_frame.grid(row=row + 2, column=0, columnspan=3, sticky="w", pady=(5, 0))

        tk.Button(
            select_frame,
            text="✅ Alle Stimmen auswählen",
            command=self._select_all_voices,
            bg=theme.BG_TERTIARY,
            fg=theme.TEXT_PRIMARY,
            font=Fonts.SMALL,
            padx=8,
            pady=2,
            cursor="hand2",
        ).pack(side="left", padx=2)

        tk.Button(
            select_frame,
            text="❌ Alle Stimmen abwählen",
            command=self._deselect_all_voices,
            bg=theme.BG_TERTIARY,
            fg=theme.TEXT_PRIMARY,
            font=Fonts.SMALL,
            padx=8,
            pady=2,
            cursor="hand2",
        ).pack(side="left", padx=2)

    def _select_all_voices(self) -> None:
        for var in self._voice_vars.values():
            var.set(True)

    def _deselect_all_voices(self) -> None:
        for var in self._voice_vars.values():
            var.set(False)

    def _fetch_piper_voices_async(self) -> None:
        """Holt die Stimmenliste von Hugging Face und aktualisiert die UI."""

        def worker():
            try:
                voices = self._fetch_piper_voices()
                self._safe_after(0, lambda: self._populate_voice_ui(voices))
            except Exception as e:
                if DEBUG_LEVEL >= 3:
                    log_debug("install_dlg", f"Piper voice fetch error: {e}")
                self._append_output(
                    "⚠️ Konnte keine aktuelle Stimmenliste von Hugging Face laden. "
                    "Verwende lokale Liste.\n",
                )

        threading.Thread(target=worker, daemon=True, name="PiperVoiceFetcher").start()

    def _fetch_piper_voices(self) -> list[str]:
        voices = []
        try:
            import requests

            page = 1
            limit = self.PIPER_API_LIMIT
            max_pages = self.PIPER_API_PAGES

            while page <= max_pages:
                url = (
                    f"https://huggingface.co/api/models?search=rhasspy/piper-voices"
                    f"&limit={limit}&page={page}"
                )
                resp = requests.get(url, timeout=15)

                if resp.status_code != 200:
                    if DEBUG_LEVEL >= 3:
                        log_debug(
                            "install_dlg",
                            f"Piper API returned {resp.status_code}",
                        )
                    break

                data = resp.json()
                if not data:
                    break

                for model in data:
                    name = model.get("modelId", "")
                    if "/" in name:
                        parts = name.split("/")[-1]
                        if parts and parts[0].islower() and "_" in parts:
                            voices.append(parts)

                if len(data) < limit:
                    break
                page += 1

            if voices:
                return sorted(set(voices))

        except ImportError:
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "install_dlg",
                    "requests nicht installiert – verwende Fallback",
                )
        except Exception as e:
            if DEBUG_LEVEL >= 3:
                log_debug("install_dlg", f"Piper API fetch failed: {e}")

        return list(self.PIPER_VOICES.keys())

