    def _check_python_package(
        self,
        pkg_name: str,
        install_name: str,
    ) -> tuple[bool, str | None]:
        module_name = self._PYTHON_PACKAGE_MODULE_MAP.get(
            install_name,
            install_name.replace("-", "_"),
        )
        try:
            spec = importlib.util.find_spec(module_name)
            if spec is None:
                return False, None
            try:
                from importlib.metadata import version

                return True, version(install_name)
            except Exception:
                return True, None
        except Exception:
            return False, None

    def _refresh_package_status(self) -> None:
        if not hasattr(self, "package_labels") or not self.package_labels:
            return

        try:
            theme = self.gui.current_theme
        except Exception:
            theme = DarkTheme()

        success_color = getattr(theme, "SUCCESS", "#238636")
        error_color = getattr(theme, "ERROR", "#f85149")

        for name, lbl in self.package_labels:
            if not lbl.winfo_exists():
                continue

            module_name = self._PYTHON_PACKAGE_MODULE_MAP.get(
                name,
                name.replace("-", "_"),
            )
            available = False

            try:
                available = importlib.util.find_spec(module_name) is not None
            except Exception:
                available = False

            was_available = self._previous_pkg_status.get(name, False)
            if available and not was_available:
                try:
                    FastLazyLoader.clear_cache(module_name)
                except Exception as e:
                    logger.debug("Ignored exception: %s", e, exc_info=True)

            self._previous_pkg_status[name] = available
            status_icon = "✅" if available else "❌"
            color = success_color if available else error_color
            lbl.config(text=f"{status_icon} {name}", fg=color)

        installed = sum(1 for status in self._previous_pkg_status.values() if status)
        total = len(self._previous_pkg_status)

        for child in self.scrollable_frame.winfo_children():
            if isinstance(child, tk.LabelFrame) and "Python-Pakete" in child.cget(
                "text",
            ):
                try:
                    if installed == total:
                        child.config(
                            text=f"🐍 Python-Pakete (pip/uv) – Alle {total} Pakete installiert ✅",
                        )
                    else:
                        child.config(
                            text=f"🐍 Python-Pakete (pip/uv) – {installed}/{total} installiert",
                        )
                except Exception as e:
                    logger.debug("Ignored exception: %s", e, exc_info=True)
                break

    def _check_pydantic_compatibility(self) -> tuple[bool, str | None, str | None]:
        """Prüft, ob pydantic und pydantic-core kompatibel sind.

        Returns:
            Tuple (kompatibel, pydantic_version, core_version).
            Bei Fehlern wird (False, None, None) zurückgegeben.

        """
        try:
            from importlib.metadata import version as pkg_version
        except ImportError:
            # Python < 3.8 – sollte nicht vorkommen
            return False, None, None

        # Versionen abrufen (fehlertolerant)
        try:
            pydantic_ver = pkg_version("pydantic")
        except Exception:
            pydantic_ver = None

        try:
            core_ver = pkg_version("pydantic-core")
        except Exception:
            core_ver = None

        # Wenn mindestens eine Version fehlt, ist keine Kompatibilität gegeben
        if not pydantic_ver or not core_ver:
            return False, pydantic_ver, core_ver

        pydantic_base = pydantic_ver.split("+")[0]
        core_base = core_ver.split("+")[0]

        # Vergleiche Major- und Minor-Version
        compatible = pydantic_base.split(".")[:2] == core_base.split(".")[:2]

        return compatible, pydantic_ver, core_ver

    def _check_and_repair_pydantic_auto(self) -> None:
        compatible, pv, cv = self._check_pydantic_compatibility()

        if not compatible and pv and cv:
            if DarkMessageBox.askyesno(
                "Pydantic‑Inkompatibilität",
                f"Die installierten Versionen von pydantic ({pv}) und pydantic-core ({cv}) "
                "sind nicht kompatibel. Soll ich die Kompatibilität automatisch reparieren?",
                parent=self.dialog,
            ):
                self._repair_pydantic_compatibility()
            else:
                self._append_output(
                    f"⚠️ Pydantic‑Inkompatibilität erkannt (pydantic={pv}, core={cv}). "
                    "Einige Funktionen (Argos‑Translate) sind deaktiviert.\n",
                )

    def _repair_pydantic_compatibility(self) -> bool:
        self._append_output("\n🔧 Repariere Pydantic-Kompatibilität...\n")

        compatible, pv, cv = self._check_pydantic_compatibility()
        if compatible:
            self._append_output("✅ Bereits kompatibel.\n")
            return True

        if pv and cv:
            self._append_output(
                f"   Gefundene Versionen: pydantic={pv}, pydantic-core={cv}\n",
            )
        else:
            self._append_output("   Mindestens eines der Pakete fehlt.\n")

        python_exe = sys.executable
        supports_break = self._pip_supports_break_system()
        cmd_base = [python_exe, "-m", "pip", "install", "--upgrade"]

        use_user = False
        use_break = False

        if not self.in_venv:
            if supports_break:
                use_break = True
            else:
                use_user = True

        for attempt in range(2):
            if self._stop_event.is_set():
                self._append_output("⏹️ Abbruch durch Benutzer.\n")
                return False

            cmd = cmd_base.copy()
            if use_break:
                cmd.append("--break-system-packages")
            elif use_user:
                cmd.append("--user")
            cmd += ["pydantic", "pydantic-core"]

            self._append_output(f"📦 Führe aus: {' '.join(cmd)}\n")

            success = self._run_subprocess(
                cmd,
                description=f"Pydantic-Update (Versuch {attempt + 1}/2)",
                timeout=180,
                stream_output=True,
                cancel_event=self._stop_event,
            )

            if success:
                compatible_after, pv_after, cv_after = (
                    self._check_pydantic_compatibility()
                )

                if compatible_after:
                    self._append_output(
                        "✅ Pydantic-Kompatibilität wiederhergestellt.\n",
                    )
                    self._append_output(
                        f"   Neue Versionen: pydantic={pv_after}, core={cv_after}\n",
                    )
                    FastLazyLoader.clear_cache("pydantic")
                    FastLazyLoader.clear_cache("pydantic_core")
                    return True
                self._append_output(
                    f"⚠️ Update schien erfolgreich, aber Kompatibilität bleibt: "
                    f"pydantic={pv_after}, core={cv_after}\n",
                )
                return False

            if attempt == 0:
                self._append_output(
                    "   Versuche ohne --user/--break-system-packages...\n",
                )
                use_user = False
                use_break = False

        self._append_output(
            "❌ Reparatur fehlgeschlagen. Bitte manuell ausführen:\n"
            f"   {python_exe} -m pip install --upgrade pydantic pydantic-core\n",
        )
        return False

    def _check_pydantic_and_update_ui(self) -> None:
        """Prüft Pydantic-Kompatibilität und zeigt ggf. Reparatur-Button an."""
        # ── 1. Grundlegende Prüfungen ──────────────────────────────────────
        if not hasattr(self, "dialog") or not self.dialog.winfo_exists():
            return

        try:
            compatible, pv, cv = self._check_pydantic_compatibility()
        except Exception:
            return

        # ── 2. Kompatibel – keine Aktion nötig ────────────────────────────
        if compatible:
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "install_dlg",
                    f"Pydantic-Kompatibilität OK (pydantic={pv}, core={cv})",
                )
            # Falls der Button existiert, ihn ausblenden (wurde bereits repariert)
            self._hide_pydantic_repair_button()
            return

        # ── 3. Inkompatibel – Warnung ausgeben und Button anzeigen ────────
        if pv and cv:
            warn_text = f"⚠️ Pydantic inkompatibel: pydantic={pv}, pydantic-core={cv}"
        else:
            warn_text = "⚠️ Pydantic oder pydantic-core nicht gefunden"

        self._append_output(f"\n{warn_text}\n")
        self._append_output(
            "   Klicken Sie auf '🔧 Pydantic reparieren', um das Problem zu beheben.\n",
        )

        # ── 4. Reparatur-Button sicher anzeigen ──────────────────────────
        self._show_pydantic_repair_button()

    def _show_pydantic_repair_button(self) -> None:
        """Zeigt den Pydantic-Reparatur-Button an (erstellt ihn bei Bedarf)."""
        # ── 1. Prüfen, ob der Button bereits existiert ────────────────────
        if (
            hasattr(self, "_pydantic_repair_btn")
            and self._pydantic_repair_btn is not None
        ):

            try:
                if self._pydantic_repair_btn.winfo_exists():

                    if not self._pydantic_repair_btn.winfo_ismapped():
                        self._pydantic_repair_btn.pack(side="left", padx=5)
                else:

                    self._pydantic_repair_btn = None
                    self._pydantic_repair_frame = None
            except tk.TclError:

                self._pydantic_repair_btn = None
                self._pydantic_repair_frame = None

        if (
            not hasattr(self, "_pydantic_repair_btn")
            or self._pydantic_repair_btn is None
        ):
            try:
                theme = self.gui.current_theme if self.gui else DarkTheme()
            except Exception:
                theme = DarkTheme()

            # Frame für den Button (einmalig)
            if (
                not hasattr(self, "_pydantic_repair_frame")
                or self._pydantic_repair_frame is None
            ):
                self._pydantic_repair_frame = tk.Frame(
                    self.scrollable_frame,
                    bg=theme.BG_PRIMARY,
                )
                self._pydantic_repair_frame.pack(fill="x", pady=5)

            self._pydantic_repair_btn = tk.Button(
                self._pydantic_repair_frame,
                text="🔧 Pydantic reparieren",
                command=self._repair_pydantic_compatibility,
                bg=theme.WARNING,
                fg=theme.TEXT_PRIMARY,
                font=Fonts.BUTTON,
                padx=10,
                cursor="hand2",
                activebackground=theme.BG_HOVER,
                activeforeground=theme.TEXT_ACCENT,
            )
            self._pydantic_repair_btn.pack(side="left", padx=5)
            ToolTip(
                self._pydantic_repair_btn,
                "Aktualisiert pydantic und pydantic-core auf kompatible Versionen.",
            )

    def _hide_pydantic_repair_button(self) -> None:
        """Blendet den Pydantic-Reparatur-Button aus (falls vorhanden)."""
        if (
            hasattr(self, "_pydantic_repair_btn")
            and self._pydantic_repair_btn is not None
        ):
            try:
                if self._pydantic_repair_btn.winfo_exists():
                    self._pydantic_repair_btn.pack_forget()
            except tk.TclError:
                pass  # Widget bereits zerstört – ignorieren

    def _pip_supports_break_system(self) -> bool:
        try:
            result = subprocess.run(
                [sys.executable, "-m", "pip", "--version"],
                capture_output=True,
                text=True,
                timeout=5,
                check=False,
            )
            if result.returncode == 0:
                version_str = result.stdout.split()[1] if result.stdout else "0"
                return tuple(int(x) for x in version_str.split(".")[:2]) >= (23, 0)
        except Exception as e:
            logger.debug("Ignored exception: %s", e, exc_info=True)
        return False

    def _export_requirements(self) -> None:
        if self._update_running:
            self._append_output("⚠️ Ein Update läuft – bitte warten.\n")
            return

        import datetime

        filename = filedialog.asksaveasfilename(
            defaultextension=".txt",
            filetypes=[("Text files", "*.txt"), ("Requirements", "requirements.txt")],
            title="requirements.txt exportieren",
            initialfile="requirements.txt",
        )

        if not filename:
            return

        self._append_output(f"📤 Exportiere Paketliste nach {filename}...\n")

        try:
            if shutil.which("uv") and not self._use_legacy_pip:
                result = subprocess.run(
                    ["uv", "pip", "freeze"],
                    capture_output=True,
                    text=True,
                    timeout=30,
                    check=False,
                )
            else:
                result = subprocess.run(
                    [sys.executable, "-m", "pip", "freeze"],
                    capture_output=True,
                    text=True,
                    timeout=30,
                    check=False,
                )

            if result.returncode != 0 or not result.stdout:
                self._append_output(f"❌ Fehler beim Export: {result.stderr}\n")
                return

            excluded = {"pip", "setuptools", "wheel", "distribute", "python"}
            lines = result.stdout.splitlines()
            filtered = [line for line in lines if line.split("==")[0] not in excluded]

            with open(filename, "w", encoding="utf-8") as f:
                f.write("# Dragon Whisperer requirements\n")
                f.write(
                    f"# Exported at {datetime.datetime.now(datetime.UTC).isoformat()}\n",
                )
                f.write(f"# Total: {len(filtered)} packages\n\n")
                f.write("\n".join(filtered))

            self._append_output(
                f"✅ {len(filtered)} Pakete exportiert (ohne Systempakete).\n",
            )
            self.export_status_label.config(
                text=f"✅ Exportiert: {os.path.basename(filename)}",
            )

        except Exception as e:
            self._append_output(f"❌ Fehler beim Export: {e}\n")

    def _import_requirements(self) -> None:
        if self._update_running:
            self._append_output("⚠️ Ein Update läuft – bitte warten.\n")
            return

        filename = filedialog.askopenfilename(
            filetypes=[("Text files", "*.txt"), ("Requirements", "requirements.txt")],
            title="requirements.txt importieren",
        )

        if not filename:
            return

        try:
            with open(filename, encoding="utf-8") as f:
                lines = [
                    line.strip()
                    for line in f
                    if line.strip() and not line.startswith("#")
                ]

            packages = []
            for line in lines:
                pkg = re.split(r"[=<>!]", line)[0].strip()
                if pkg:
                    packages.append(pkg)

            if not packages:
                self._append_output("⚠️ Keine Pakete in der Datei gefunden.\n")
                return

        except Exception as e:
            self._append_output(f"❌ Fehler beim Lesen der Datei: {e}\n")
            return

        self._append_output(f"📥 Importiere {len(packages)} Pakete aus {filename}...\n")
        self._install_python_packages(packages, upgrade=False)

    def install_selected(self) -> None:
        if self._closed or not self.dialog.winfo_exists():
            return

        sys_pkgs = [pkg for pkg, var in self.sys_vars.items() if var.get()]
        py_pkgs = [pkg for pkg, var in self.py_vars.items() if var.get()]
        voices = [voice for voice, var in self._voice_vars.items() if var.get()]

        if not (sys_pkgs or py_pkgs or voices):
            self.status_var.set("❌ Nichts ausgewählt")
            DarkMessageBox.showinfo(
                "Keine Auswahl",
                "Es wurden keine Pakete oder Stimmen ausgewählt.\n"
                "Bitte wählen Sie mindestens ein Paket oder eine Stimme aus.",
                parent=self.dialog,
            )
            return

        if self._update_running:
            self._append_output("⚠️ Ein Update läuft bereits – bitte warten.\n")
            return

        self._update_running = True
        self._current_install_phase = InstallPhase.PREPARING

        if hasattr(self, "output_text") and self.output_text.winfo_exists():
            try:
                self.output_text.delete("1.0", "end")
            except Exception as e:
                logger.debug("Ignored exception: %s", e, exc_info=True)

        self._append_output("🚀 Der Drache erhebt sich – Installation beginnt...\n")
        self._append_output(
            f"📦 Systempakete: {', '.join(sys_pkgs) if sys_pkgs else 'keine'}\n",
        )
        self._append_output(
            f"🐍 Python-Pakete: {', '.join(py_pkgs) if py_pkgs else 'keine'}\n",
        )
        self._append_output(
            f"🎤 Piper-Stimmen: {', '.join(voices) if voices else 'keine'}\n\n",
        )

        self._enable_ui(False)

        if hasattr(self, "cancel_btn") and self.cancel_btn.winfo_exists():
            try:
                self.cancel_btn.config(state="normal")
            except Exception as e:
                logger.debug("Ignored exception: %s", e, exc_info=True)

        self.status_var.set("⚙️ Installation läuft...")
        self._update_progress(0.0, "Starte…")
        self._stop_event.clear()

        thread = threading.Thread(
            target=self._install_worker,
            args=(sys_pkgs, py_pkgs, voices),
            daemon=True,
            name="InstallDependency-Worker",
        )

        try:
            with self._active_threads_lock:
                self._active_threads.append(thread)
            thread.start()
        except RuntimeError as exc:
            logger.error("Installations-Thread konnte nicht gestartet werden: %s", exc)
            self._append_output(f"❌ Fehler beim Starten der Installation: {exc}\n")
            self._update_running = False
            self._current_install_phase = InstallPhase.ERROR
            self._enable_ui(True)

            if hasattr(self, "cancel_btn") and self.cancel_btn.winfo_exists():
                try:
                    self.cancel_btn.config(state="disabled")
                except Exception as e:
                    logger.debug("Ignored exception: %s", e, exc_info=True)

            self.status_var.set("❌ Fehler beim Starten")

    def _install_worker(
        self,
        sys_pkgs: list[str],
        py_pkgs: list[str],
        voices: list[str],
    ) -> None:
        total_steps = len(sys_pkgs) + (1 if py_pkgs else 0) + (1 if voices else 0)
        current_step = 0

        def update_progress(
            step_text: str,
            phase: InstallPhase = InstallPhase.INSTALLING_SYSTEM,
        ) -> None:
            pct = (current_step / max(total_steps, 1)) * 100
            self._current_install_phase = phase
            self._update_progress(pct, step_text)

        results: list[InstallationResult] = []

        try:
            for pkg in sys_pkgs:
                if self._stop_event.is_set():
                    self._append_output("⏹️ Systempakete‑Installation abgebrochen\n")
                    break

                self._append_output(f"\n📦 Installiere Systempaket: {pkg}\n")
                current_step += 1
                update_progress(f"Systempaket: {pkg}", InstallPhase.INSTALLING_SYSTEM)

                start_time = time.perf_counter()
                success = self._install_system_package(pkg)
                duration = time.perf_counter() - start_time

                result = InstallationResult(
                    success=success,
                    package=pkg,
                    message=f"{'✅' if success else '❌'} {pkg}",
                    duration=duration,
                )
                results.append(result)
                self._append_output(f"{result.message} ({duration:.1f}s)\n")

                if success:
                    self._is_tool_installed(pkg, force_refresh=True)

            if py_pkgs and not self._stop_event.is_set():
                self._append_output(f"\n🐍 Python‑Pakete: {', '.join(py_pkgs)}\n")
                current_step += 1
                update_progress(
                    f"Python‑Pakete ({len(py_pkgs)} Stück)",
                    InstallPhase.INSTALLING_PYTHON,
                )

                start_time = time.perf_counter()
                success = self._install_python_packages(py_pkgs, upgrade=True)
                duration = time.perf_counter() - start_time

                results.append(
                    InstallationResult(
                        success=success,
                        package="Python-Pakete",
                        message=f"{'✅' if success else '❌'} Python‑Pakete",
                        duration=duration,
                    ),
                )
                self._append_output(
                    f"{'✅' if success else '❌'} Python‑Pakete ({duration:.1f}s)\n",
                )

            if voices and not self._stop_event.is_set():
                self._append_output(f"\n🎤 Piper‑Stimmen: {', '.join(voices)}\n")
                current_step += 1
                update_progress(
                    f"Piper‑Stimmen ({len(voices)} Stück)",
                    InstallPhase.DOWNLOADING_VOICES,
                )

                start_time = time.perf_counter()
                success = self._download_piper_voices(voices)
                duration = time.perf_counter() - start_time

                results.append(
                    InstallationResult(
                        success=success,
                        package="Piper-Stimmen",
                        message=f"{'✅' if success else '❌'} Piper‑Stimmen",
                        duration=duration,
                    ),
                )
                self._append_output(
                    f"{'✅' if success else '❌'} Piper‑Stimmen ({duration:.1f}s)\n",
                )

            self._update_progress(100.0, "Fertig ✅")
            self._current_install_phase = InstallPhase.FINISHED

            success_count = sum(1 for r in results if r.success)
            total_count = len(results)

            if total_count > 0:
                summary = (
                    f"\n📊 Zusammenfassung: {success_count}/{total_count} erfolgreich"
                )
                if success_count == total_count:
                    summary += " – 🎉 Alles hat geklappt!"
                else:
                    summary += " – ⚠️ Einige Installationen fehlgeschlagen. Siehe oben."
                self._append_output(summary + "\n")

            final_msg = (
                "✅ Installation abgeschlossen – bereit zum Abheben!"
                if not self._stop_event.is_set()
                else "⏹️ Installation abgebrochen."
            )

            try:
                self.status_var.set(final_msg)
            except Exception as e:
                logger.debug("Ignored exception: %s", e, exc_info=True)

            if not self._stop_event.is_set():
                self._refresh_package_status()
                self._safe_after(100, self._fetch_piper_voices_async)

        except Exception as e:
            self._append_output(f"\n❌ Unerwarteter Fehler: {e}\n")
            self._update_progress(0.0, "Fehler ❌")
            self._current_install_phase = InstallPhase.ERROR

            try:
                self.status_var.set("❌ Fehler bei Installation")
            except Exception as e:
                logger.debug("Ignored exception: %s", e, exc_info=True)

            logger.exception("Fehler in _install_worker")

        finally:
            self._update_running = False
            self._enable_ui(True)

            if not self._stop_event.is_set():
                self._current_install_phase = InstallPhase.FINISHED
            else:
                self._current_install_phase = InstallPhase.CANCELLED

            current = threading.current_thread()
            with self._active_threads_lock:
                try:
                    self._active_threads.remove(current)
                except Exception as e:
                    logger.debug("Ignored exception: %s", e, exc_info=True)

    def _install_system_package(self, pkg: str) -> bool:
        pkg_data = self.SYSTEM_PACKAGES.get(pkg, {})

        if IS_WINDOWS and "pip" in pkg_data:
            self._append_output(f"🐍 Installiere {pkg} über pip...\n")
            return self._install_python_packages([pkg_data["pip"]], upgrade=True)

        if self.pkg_manager == "winget" and "winget" in pkg_data:
            if not self._is_admin():
                self._append_output(
                    "⚠️ Administratorrechte erforderlich! Bitte als Admin neu starten.\n",
                )
                return False

            cmd = [
                "winget",
                "install",
                "-e",
                "--id",
                pkg_data["winget"],
                "--accept-package-agreements",
                "--accept-source-agreements",
            ]
            self._append_output(f"📦 Installiere {pkg} über winget...\n")

            success = self._run_subprocess(
                cmd,
                f"Installiere {pkg}",
                timeout=self.TIMEOUT_SYSTEM_INSTALL,
            )

            if success and self._is_tool_installed(pkg, force_refresh=True):
                self._append_output(
                    f"✅ {pkg} wurde erfolgreich installiert und gefunden.\n",
                )
                return True
            return False

        if self.pkg_manager in pkg_data:
            cmd = self._get_package_manager_command(pkg_data[self.pkg_manager])
            if cmd:
                self._append_output(
                    f"📦 Installiere {pkg} über {self.pkg_manager}...\n",
                )
                success = self._run_subprocess(
                    cmd,
                    f"Installiere {pkg}",
                    timeout=self.TIMEOUT_SYSTEM_INSTALL,
                )
                if success and self._is_tool_installed(pkg, force_refresh=True):
                    self._append_output(f"✅ {pkg} wurde erfolgreich installiert.\n")
                    return True
                return False

        if "pip" in pkg_data:
            self._append_output(f"🐍 Installiere {pkg} über pip...\n")
            return self._install_python_packages([pkg_data["pip"]], upgrade=True)

        if "fallback" in pkg_data:
            self._append_output(f"🔄 Verwende Fallback-Installation für {pkg}...\n")
            return self._run_fallback_install(pkg_data["fallback"])

        self._append_output(f"❌ Keine Installationsmethode für {pkg}.\n")
        return False

    def _get_package_manager_command(self, package_name: str) -> list[str]:
        manager = self.pkg_manager

        if manager == "apt":
            return ["sudo", "apt", "install", "-y", package_name]
        if manager == "dnf":
            return ["sudo", "dnf", "install", "-y", package_name]
        if manager == "yum":
            return ["sudo", "yum", "install", "-y", package_name]
        if manager == "zypper":
            return ["sudo", "zypper", "--non-interactive", "install", package_name]
        if manager == "pacman":
            return ["sudo", "pacman", "-S", "--noconfirm", package_name]
        if manager == "apk":
            return ["sudo", "apk", "add", package_name]
        if manager == "brew":
            return ["brew", "install", package_name]
        if manager == "winget":
            return [
                "winget",
                "install",
                "-e",
                "--id",
                package_name,
                "--source",
                "winget",
                "--accept-package-agreements",
                "--accept-source-agreements",
            ]

        return []

    def _run_fallback_install(self, command: str) -> bool:
        result_container = [False]
        user_responded = threading.Event()

        def _gui_interaction():
            if not self.dialog or not self.dialog.winfo_exists():
                user_responded.set()
                return

            try:
                self.dialog.clipboard_clear()
                self.dialog.clipboard_append(command)
                copied = True
            except Exception:
                copied = False

            self._append_output(
                f"\n⚠️  Aus Sicherheitsgründen wird der folgende Befehl NICHT automatisch ausgeführt.\n"
                f"Bitte führen Sie ihn manuell in einem Terminal aus.\n\n"
                f"    {command}\n\n"
                f"{'📋 Der Befehl wurde in die Zwischenablage kopiert.' if copied else ''}",
            )
            self.dialog.update_idletasks()

            if IS_WINDOWS and self.pkg_manager == "manual":
                if DarkMessageBox.askyesno(
                    "Terminal öffnen?",
                    "Möchten Sie eine Eingabeaufforderung mit dem Befehl öffnen?",
                    parent=self.dialog,
                ):
                    try:
                        subprocess.Popen(
                            ["cmd", "/K", command],
                            creationflags=subprocess.CREATE_NEW_CONSOLE,
                        )
                    except Exception as e:
                        self._append_output(f"❌ Konnte Terminal nicht öffnen: {e}\n")

            DarkMessageBox.showinfo(
                title="Manuelle Installation erforderlich",
                message=(
                    f"Bitte öffnen Sie ein Terminal und führen Sie den folgenden Befehl aus:\n\n"
                    f"    {command}\n\n"
                    f"Der Befehl wurde in die Zwischenablage kopiert.\n"
                    f"Klicken Sie anschließend auf OK und beantworten Sie die folgende Frage."
                ),
                parent=self.dialog,
                timeout=120,
            )

            response = DarkMessageBox.askyesno(
                title="Installation bestätigen",
                message="Wurde der Befehl erfolgreich ausgeführt?",
                parent=self.dialog,
                timeout=120,
            )

            if response is True:
                result_container[0] = True

            user_responded.set()

        if self.dialog and self.dialog.winfo_exists():
            self.dialog.after_idle(_gui_interaction)
        else:
            self._append_output(
                f"\n⚠️  Fallback-Installation erfordert manuelle Ausführung:\n    {command}\n",
            )
            return False

        if not user_responded.wait(timeout=130):
            self._append_output(
                "⏰ Zeitüberschreitung – Installation nicht bestätigt.\n",
            )
            return False

        return result_container[0]

    def _install_python_packages(
        self,
        packages: list[str],
        upgrade: bool = False,
    ) -> bool:
        if not packages:
            self._append_output("ℹ️ Keine Python‑Pakete angegeben – überspringe.\n")
            return True

        python_exe = sys.executable

        use_uv = shutil.which("uv") and not self._use_legacy_pip
        if use_uv:
            self._append_output("🐍 Verwende `uv` für beschleunigte Installation...\n")
        else:
            self._append_output("🔍 Prüfe pip...\n")

        supports_break_system = False

        if not use_uv:
            try:
                result = subprocess.run(
                    [python_exe, "-m", "pip", "--version"],
                    capture_output=True,
                    text=True,
                    check=True,
                    timeout=10,
                )
                pip_version_str = result.stdout.split()[1] if result.stdout else "0"
                supports_break_system = tuple(
                    int(x) for x in pip_version_str.split(".")[:2]
                ) >= (23, 0)
            except Exception as e:
                self._append_output(f"❌ pip ist nicht funktionsfähig: {e}\n")
                return False

        def run_installer(extra_args: list[str], description: str) -> str | None:
            if use_uv:
                cmd = ["uv", "pip", "install"]
                if upgrade:
                    cmd.append("--upgrade")
                cmd.extend(extra_args)
                cmd.extend(packages)

                env = os.environ.copy()
                env["PYTHONUNBUFFERED"] = "1"
                env["PYTHONUTF8"] = "1"

                return self._run_subprocess(
                    cmd,
                    description,
                    env=env,
                    timeout=self.TIMEOUT_PIP_INSTALL,
                )
            cmd = [
                python_exe,
                "-m",
                "pip",
                "install",
                "--no-cache-dir",
                "--disable-pip-version-check",
            ]
            if upgrade:
                cmd.append("--upgrade")

            if (
                not self.in_venv
                and "--user" not in extra_args
                and "--break-system-packages" not in extra_args
            ):
                cmd.append("--user")

            cmd.extend(extra_args)
            cmd.extend(packages)

            env = os.environ.copy()
            env["PYTHONUNBUFFERED"] = "1"
            env["PYTHONUTF8"] = "1"

            return self._run_subprocess(
                cmd,
                description,
                env=env,
                timeout=self.TIMEOUT_PIP_INSTALL,
            )

        output = run_installer([], "Pakete installieren")

        if output is not None:
            self._append_output("✅ Installation erfolgreich.\n")

            for pkg in packages:
                module_name = pkg.replace("-", "_")
                try:
                    FastLazyLoader.clear_cache(module_name)
                except Exception as e:
                    logger.debug("Ignored exception: %s", e, exc_info=True)

            return True

        stderr_lower = self._last_stderr.lower() if self._last_stderr else ""

        if "externally-managed-environment" in stderr_lower:
            self._append_output(
                "\n⚠️  Ihr System schützt die systemweite Python‑Installation (PEP 668).\n",
            )

            if not self.in_venv:
                if DarkMessageBox.askyesno(
                    "Virtuelle Umgebung empfohlen",
                    "Möchten Sie eine virtuelle Umgebung (venv) erstellen und "
                    "Dragon Whisperer dort neu starten?\n\n"
                    "Dies ist die sicherste Methode und wird dringend empfohlen.",
                    parent=self.dialog,
                ):
                    self._create_venv_and_restart()
                    return False
                if not supports_break_system:
                    self._append_output(
                        "⚠️ Ihre pip‑Version unterstützt --break-system-packages nicht.\n"
                        "Bitte aktualisieren Sie pip: python -m pip install --upgrade pip\n",
                    )
                elif DarkMessageBox.askyesno(
                    "⚠️  Riskante Installation",
                    "Möchten Sie die Pakete trotzdem systemweit installieren?\n\n"
                    "Dies kann Ihre System‑Python‑Installation beschädigen!\n"
                    "Nur fortfahren, wenn Sie wissen, was Sie tun.",
                    parent=self.dialog,
                ):
                    output2 = run_installer(
                        ["--break-system-packages"],
                        "Installation mit --break-system-packages",
                    )
                    if output2 is not None:
                        return True
                    self._append_output(
                        "❌ Auch die erzwungene Installation schlug fehl.\n",
                    )
                else:
                    self._append_output("Installation abgebrochen.\n")
            else:
                self._append_output(
                    "❌ Unerwarteter Fehler: externally-managed-environment innerhalb eines venv.\n"
                    "Bitte überprüfen Sie Ihre venv‑Konfiguration.\n",
                )

        elif "subprocess-exited-with-error" in stderr_lower or "thinc" in stderr_lower:
            self._append_output(
                "\n💡 Tipp:\n"
                "Das Paket konnte nicht kompiliert werden. Bitte installieren Sie einen C++ Compiler:\n",
            )

            if sys.platform.startswith("linux"):
                self._append_output(
                    "  • Debian/Ubuntu:  sudo apt install build-essential python3-dev\n"
                    "  • Fedora/RHEL:    sudo dnf install python3-devel gcc\n"
                    "  • Arch/Manjaro:   sudo pacman -S base-devel python3\n"
                    "  • openSUSE:       sudo zypper install python3-devel gcc\n",
                )
            elif IS_WINDOWS:
                self._append_output(
                    "  • Installieren Sie die Microsoft C++ Build Tools:\n"
                    "    https://visualstudio.microsoft.com/visual-cpp-build-tools/\n",
                )
            else:
                self._append_output(
                    "  • Stellen Sie sicher, dass ein C++ Compiler (gcc/clang) und python3-dev installiert sind.\n",
                )

            self._append_output(
                "\n🔄 Versuche Installation mit --only-binary (ohne Kompilierung)...\n",
            )
            output3 = run_installer(
                ["--only-binary", ":all:"],
                "Installation (binary only)",
            )

            if output3 is not None:
                return True
            self._append_output("❌ Auch der Binary‑Fallback fehlgeschlagen.\n")

        else:
            if not IS_WINDOWS:
                self._append_output(
                    "\n💡 Tipp:\n"
                    "Stellen Sie sicher, dass ein C++ Compiler (gcc/clang) und die "
                    "Python‑Entwicklungsheader installiert sind:\n"
                    "  • Debian/Ubuntu:  sudo apt install build-essential python3-dev\n"
                    "  • Fedora/RHEL:    sudo dnf install python3-devel gcc\n"
                    "  • Arch/Manjaro:   sudo pacman -S base-devel python3\n"
                    "  • openSUSE:       sudo zypper install python3-devel gcc\n",
                )
            elif IS_WINDOWS:
                self._append_output(
                    "\n💡 Tipp:\n"
                    "Einige Pakete benötigen einen C++ Compiler.\n"
                    "Installieren Sie die Microsoft C++ Build Tools:\n"
                    "https://visualstudio.microsoft.com/visual-cpp-build-tools/\n",
                )

            if not self.in_venv:
                self._append_output(
                    "\n🔄 Versuche Installation ohne --user (systemweit, falls erlaubt)...\n",
                )
                output4 = run_installer(["--system"], "Installation (system-wide)")

                if output4 is not None:
                    return True
                self._append_output(
                    "❌ Auch die systemweite Installation fehlgeschlagen.\n",
                )
            else:
                self._append_output("❌ Installation fehlgeschlagen.\n")

        return False

    def _create_venv_and_restart(self) -> None:
        venv_dir = os.path.join(os.getcwd(), "venv")

        if os.path.exists(venv_dir):
            if not DarkMessageBox.askyesno(
                "venv existiert",
                f"Ein venv existiert bereits unter {venv_dir}. Soll ich es überschreiben?",
                parent=self.dialog,
            ):
                return

            try:
                shutil.rmtree(venv_dir)
                self._append_output("🗑️ Altes venv gelöscht.\n")
            except Exception as e:
                self._append_output(f"❌ Konnte bestehendes venv nicht löschen: {e}\n")
                return

        self._append_output(f"🔄 Erstelle virtuelle Umgebung in {venv_dir}...\n")

        try:
            subprocess.run(
                [sys.executable, "-m", "venv", venv_dir],
                check=True,
                capture_output=True,
                text=True,
            )
        except subprocess.CalledProcessError as e:
            self._append_output(f"❌ Fehler beim Erstellen des venv: {e.stderr}\n")
            return

        python_exe = os.path.join(venv_dir, "bin", "python")
        if IS_WINDOWS:
            python_exe = os.path.join(venv_dir, "Scripts", "python.exe")

        self._append_output("📦 Installiere pip und kritische Pakete im venv...\n")

        try:
            subprocess.run(
                [python_exe, "-m", "pip", "install", "--upgrade", "pip"],
                check=True,
                capture_output=True,
            )

            pkg_list = list(self.CRITICAL_PYTHON_PACKAGES)
            subprocess.run(
                [python_exe, "-m", "pip", "install", *pkg_list],
                check=True,
                capture_output=True,
            )

            self._append_output(f"✅ {len(pkg_list)} kritische Pakete installiert.\n")

        except subprocess.CalledProcessError as e:
            self._append_output(
                f"❌ Fehler bei der Installation im venv: {e.stderr.decode()}\n",
            )
            return

        self._append_output(
            "✅ Virtuelle Umgebung erfolgreich erstellt. Starte neu...\n",
        )

        script = os.path.abspath(sys.argv[0])
        args = sys.argv[1:]

        try:
            if IS_WINDOWS:
                subprocess.Popen(
                    [python_exe, script, *args],
                    creationflags=subprocess.CREATE_NEW_CONSOLE,
                )
            else:
                subprocess.Popen([python_exe, script, *args])
        except Exception as e:
            self._append_output(f"❌ Fehler beim Neustart: {e}\n")
            return

        self._append_output("🔄 Beende aktuellen Prozess...\n")
        sys.exit(0)

    # ─── Piper‑Stimmen‑Download (parallel) ─────────────────────────────

    def _download_piper_voices(self, voices: list[str]) -> bool:
        if not voices:
            return True

        try:
            cache_dir = TTSManager.get_piper_cache_dir()
        except Exception:
            cache_dir = os.path.join(os.path.expanduser("~"), "piper_models")

        os.makedirs(cache_dir, exist_ok=True)

        BASE_URL = "https://huggingface.co/rhasspy/piper-voices/resolve/main"

        try:
            import requests

            use_requests = True
        except ImportError:
            use_requests = False
            self._append_output(
                "⚠️ requests nicht installiert – verwende urllib (langsamer, kein Resume)\n",
            )

        def download_file(remote_path: str, local_path: str, description: str) -> bool:
            url = f"{BASE_URL}/{remote_path}"
            max_attempts = 3
            backoff_base = 2.0

            if os.path.exists(local_path):
                expected_size = None

                if use_requests:
                    try:
                        with requests.Session() as sess:
                            head = sess.head(url, timeout=10)
                            if head.status_code == 200:
                                expected_size = int(
                                    head.headers.get("content-length", 0),
                                )
                    except Exception as e:
                        logger.debug("Ignored exception: %s", e, exc_info=True)

                if (
                    expected_size is not None
                    and os.path.getsize(local_path) == expected_size
                ):
                    return True

                if expected_size is not None:
                    self._append_output(
                        f"  ⚠️ {description} unvollständig "
                        f"({os.path.getsize(local_path)} / {expected_size} Bytes) – lade neu\n",
                    )
                    try:
                        os.unlink(local_path)
                    except Exception as e:
                        logger.debug("Ignored exception: %s", e, exc_info=True)

            for attempt in range(1, max_attempts + 1):
                if self._stop_event.is_set():
                    self._append_output(
                        f"    ⏹️ Download von {description} abgebrochen\n",
                    )
                    return False

                try:
                    if use_requests:
                        headers = {
                            "User-Agent": "DragonWhisperer/4.0",
                            "Accept": "*/*",
                        }

                        resume_header = None
                        if os.path.exists(local_path):
                            existing_size = os.path.getsize(local_path)
                            resume_header = {"Range": f"bytes={existing_size}-"}
                            headers.update(resume_header)
                            if DEBUG_LEVEL >= 3:
                                self._append_output(
                                    f"    Resume: versuche ab Byte {existing_size}\n",
                                )

                        with requests.Session() as sess:
                            sess.headers.update(headers)
                            resp = sess.get(
                                url,
                                stream=True,
                                timeout=60,
                                headers=resume_header or {},
                            )
                            resp.raise_for_status()

                            total_size = int(resp.headers.get("content-length", 0))
                            existing = (
                                os.path.getsize(local_path)
                                if os.path.exists(local_path)
                                else 0
                            )

                            mode = (
                                "ab"
                                if resume_header and resp.status_code == 206
                                else "wb"
                            )

                            with open(local_path, mode) as f:
                                downloaded = existing
                                for chunk in resp.iter_content(chunk_size=8192):
                                    if self._stop_event.is_set():
                                        f.close()
                                        os.unlink(local_path)
                                        return False
                                    if chunk:
                                        f.write(chunk)
                                        downloaded += len(chunk)
                                        if total_size > 0:
                                            percent = (downloaded / total_size) * 100
                                            if int(percent) % 5 == 0:
                                                self._update_progress(
                                                    percent,
                                                    f"{description}: {percent:.0f}%",
                                                )

                            if total_size > 0 and downloaded != total_size:
                                raise RuntimeError(
                                    f"Unvollständiger Download: {downloaded} / {total_size} Bytes",
                                )

                            return True

                    else:
                        import urllib.request

                        req = urllib.request.Request(
                            url,
                            headers={"User-Agent": "DragonWhisperer/4.0"},
                        )

                        with urllib.request.urlopen(req, timeout=60) as resp:
                            total_size = int(resp.headers.get("Content-Length", 0))

                            with open(local_path, "wb") as f:
                                downloaded = 0
                                while True:
                                    chunk = resp.read(8192)
                                    if not chunk:
                                        break
                                    if self._stop_event.is_set():
                                        f.close()
                                        os.unlink(local_path)
                                        return False
                                    f.write(chunk)
                                    downloaded += len(chunk)
                                    if total_size > 0:
                                        percent = (downloaded / total_size) * 100
                                        if int(percent) % 5 == 0:
                                            self._update_progress(
                                                percent,
                                                f"{description}: {percent:.0f}%",
                                            )

                            return True

                except Exception as e:
                    error_msg = str(e)
                    self._append_output(
                        f"    ⚠️ Versuch {attempt}/{max_attempts} fehlgeschlagen: {error_msg[:100]}\n",
                    )

                    if attempt < max_attempts:
                        delay = min(10.0, backoff_base**attempt)
                        self._append_output(
                            f"    Warte {delay:.1f}s vor nächstem Versuch...\n",
                        )
                        time.sleep(delay)
                    else:
                        self._append_output(
                            f"    ❌ Endgültiger Fehler bei {description}: {error_msg}\n",
                        )
                        return False

            return False

        def download_voice(voice: str, idx: int, total: int) -> tuple[str, bool]:
            if self._stop_event.is_set():
                return voice, False

            self._append_output(
                f"\n📥 Lade Stimme {voice} ({idx}/{total}) herunter...\n",
            )

            model_file = f"{voice}.onnx"
            json_file = f"{voice}.onnx.json"

            model_path = os.path.join(cache_dir, model_file)
            json_path = os.path.join(cache_dir, json_file)

            parts = voice.split("-")

            if len(parts) >= 3:
                lang_full, speaker, quality = parts[0], parts[1], parts[2]
                lang_short = lang_full.split("_")[0]
                remote_dir = f"{lang_short}/{lang_full}/{speaker}/{quality}"
            else:
                remote_dir = voice
                self._append_output(f"  ⚠️ Unerwartetes Voice-Format: {voice}\n")

            model_ok = True
            if not os.path.exists(model_path) or os.path.getsize(model_path) == 0:
                self._append_output(f"  📦 Lade Modell {model_file}...\n")
                model_ok = download_file(
                    f"{remote_dir}/{model_file}",
                    model_path,
                    f"Modell {voice}",
                )
                if not model_ok:
                    return voice, False
            else:
                self._append_output(f"  ✅ Modell {model_file} bereits vorhanden.\n")

            json_ok = True
            if not os.path.exists(json_path) or os.path.getsize(json_path) == 0:
                self._append_output(f"  📄 Lade Konfiguration {json_file}...\n")
                json_ok = download_file(
                    f"{remote_dir}/{json_file}",
                    json_path,
                    f"Konfiguration {voice}",
                )
                if not json_ok:
                    return voice, False
            else:
                try:
                    with open(json_path, encoding="utf-8") as f:
                        json.load(f)
                    self._append_output(
                        f"  ✅ Konfiguration {json_file} bereits vorhanden (gültig).\n",
                    )
                except Exception:
                    self._append_output(
                        f"  ⚠️ Konfiguration {json_file} ist beschädigt – lade neu...\n",
                    )
                    os.unlink(json_path)
                    json_ok = download_file(
                        f"{remote_dir}/{json_file}",
                        json_path,
                        f"Konfiguration {voice}",
                    )
                    if not json_ok:
                        return voice, False

            if model_ok and json_ok:
                self._append_output(f"  ✅ {voice} vollständig installiert.\n")
                return voice, True
            return voice, False

        overall_success = True
        total_voices = len(voices)
        results: dict[str, bool] = {}

        with ThreadPoolExecutor(
            max_workers=self.MAX_PARALLEL_VOICE_DOWNLOADS,
        ) as executor:
            futures = {}

            for idx, voice in enumerate(voices, 1):
                if self._stop_event.is_set():
                    break
                future = executor.submit(download_voice, voice, idx, total_voices)
                futures[future] = voice

            for future in as_completed(futures):
                voice = futures[future]
                try:
                    _, success = future.result(timeout=300)
                    results[voice] = success
                    if not success:
                        overall_success = False
                except Exception as e:
                    self._append_output(f"❌ Fehler beim Download von {voice}: {e}\n")
                    results[voice] = False
                    overall_success = False

        if overall_success and hasattr(self, "gui") and self.gui is not None:
            try:
                tts = getattr(self.gui, "tts_manager", None)
                if tts and hasattr(tts, "get_installed_piper_voices"):
                    with tts._models_cache_lock:
                        tts._models_cache = []
                        tts._models_cache_time = 0.0
                    self._append_output("\n🔄 Piper‑Stimmen‑Cache aktualisiert.\n")
            except Exception as e:
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "install_dlg",
                        f"Konnte TTSManager-Cache nicht aktualisieren: {e}",
                    )

        return overall_success

    def update_critical_packages(self) -> None:
        if self._update_running:
            self._append_output("⚠️ Ein Update läuft bereits – bitte warten.\n")
            return

        if not self.in_venv and not self._is_admin():
            self._append_output(
                "\n⚠️ Sie führen ein systemweites Update ohne venv durch.\n"
                "Dies kann Ihre Python‑Installation beschädigen.\n"
                "Empfehlung: Nutzen Sie eine virtuelle Umgebung (venv).\n\n",
            )

            if not DarkMessageBox.askyesno(
                "Systemweites Update",
                "Möchten Sie trotzdem fortfahren? (Nicht empfohlen)",
                parent=self.dialog,
            ):
                self._append_output("Update abgebrochen.\n")
                return

        self._update_running = True
        self._current_install_phase = InstallPhase.UPDATING_CRITICAL

        self._append_output("\n⚠️ KRITISCHE PAKETE AKTUALISIEREN\n")
        for pkg in sorted(self.CRITICAL_PYTHON_PACKAGES):
            self._append_output(f"  • {pkg}\n")
        self._append_output("\n")

        self._enable_ui(False)

        if hasattr(self, "cancel_btn") and self.cancel_btn.winfo_exists():
            self.cancel_btn.config(state="normal")

        self.status_var.set("⏳ Kritische Pakete werden aktualisiert...")

        supports_break_system = self._pip_supports_break_system()

        thread = threading.Thread(
            target=self._update_critical_worker,
            args=(supports_break_system,),
            daemon=True,
            name="InstallDependency-CriticalUpdateWorker",
        )

        with self._active_threads_lock:
            self._active_threads.append(thread)

        thread.start()

    def _update_critical_worker(self, supports_break_system: bool = False) -> None:
        python_exe = sys.executable
        packages = list(self.CRITICAL_PYTHON_PACKAGES)

        if not packages:
            self._append_output("ℹ️ Keine kritischen Pakete definiert.\n")
            self.status_var.set("ℹ️ Keine kritischen Pakete")
            return

        total = len(packages)
        self._append_output(f"⚠️ Aktualisiere {total} kritische Pakete...\n\n")

        updated_pkgs = []
        failed_pkgs = []
        skipped_pkgs = []

        def _get_timeout_for_package(pkg_name: str) -> int:
            pkg_lower = pkg_name.lower()
            if any(x in pkg_lower for x in ("nvidia", "cuda", "cudnn")):
                return 900
            if pkg_lower in ("torch", "pytorch", "tensorflow", "transformers"):
                return 600
            if pkg_lower in ("pytorch-lightning", "stanza", "spacy", "thinc"):
                return 400
            if "opencv" in pkg_lower or "pillow" in pkg_lower:
                return 300
            if "scipy" in pkg_lower or "numpy" in pkg_lower:
                return 240
            if "grpcio" in pkg_lower or "protobuf" in pkg_lower:
                return 300
            return 180

        MAX_RETRIES = 2

        for idx, pkg in enumerate(packages, 1):
            if self._stop_event.is_set():
                self._append_output("⏹️ Abbruch durch Benutzer\n")
                break

            progress = int((idx - 1) / total * 100)
            self._update_progress(progress, f"Aktualisiere {pkg} ({idx}/{total})")
            self._append_output(f"📦 ({idx}/{total}) Aktualisiere {pkg}...\n")

            if pkg in self.UPDATE_BLACKLIST:
                self._append_output(f"  ⏭️ überspringe {pkg} (systemkritisch)\n")
                skipped_pkgs.append(pkg)
                continue

            use_uv = shutil.which("uv") and not self._use_legacy_pip

            if use_uv:
                cmd = ["uv", "pip", "install", "--upgrade", pkg]
            else:
                cmd = [
                    python_exe,
                    "-m",
                    "pip",
                    "install",
                    "--upgrade",
                    "--no-cache-dir",
                    "--disable-pip-version-check",
                ]

                if not self.in_venv:
                    if supports_break_system:
                        cmd.append("--break-system-packages")
                    else:
                        cmd.append("--user")

                cmd.append(pkg)

            timeout = _get_timeout_for_package(pkg)

            success = False
            last_exception = None

            for attempt in range(MAX_RETRIES):
                if self._stop_event.is_set():
                    break

                proc = None

                try:
                    proc = subprocess.Popen(
                        cmd,
                        stdout=subprocess.PIPE,
                        stderr=subprocess.PIPE,
                        text=True,
                        encoding="utf-8",
                        errors="replace",
                        env=os.environ.copy(),
                    )

                    _stdout, stderr = proc.communicate(timeout=timeout + (attempt * 30))

                    if proc.returncode == 0:
                        success = True
                        break
                    last_exception = f"Exit {proc.returncode}: {stderr[:200] if stderr else 'no stderr'}"

                    if "externally-managed-environment" in stderr.lower():
                        self._append_output(
                            "    💡 Tipp: Verwenden Sie eine virtuelle Umgebung (venv) oder "
                            "installieren Sie mit `--break-system-packages` (riskant).\n",
                        )
                        break

                    if "subprocess-exited-with-error" in stderr.lower():
                        self._append_output(
                            "    💡 Tipp: Einige Pakete benötigen einen C++ Compiler.\n"
                            "    Installieren Sie build-essential (Linux) oder Visual C++ Build Tools (Windows).\n",
                        )
                        break

                    if "timeout" in stderr.lower() or "connection" in stderr.lower():
                        self._append_output(
                            f"    ⚠️ Temporärer Fehler (Versuch {attempt + 1}/{MAX_RETRIES}). "
                            "Wiederhole nach kurzer Pause...\n",
                        )
                        time.sleep(2 ** (attempt + 1))
                        continue

                    if attempt < MAX_RETRIES - 1:
                        self._append_output(
                            f"    ⚠️ Fehler (Versuch {attempt + 1}/{MAX_RETRIES}). Wiederhole...\n",
                        )
                        time.sleep(1)
                        continue

                except subprocess.TimeoutExpired:
                    last_exception = f"Timeout nach {timeout + attempt * 30}s"

                    if proc is not None:
                        proc.kill()
                        proc.wait()

                    if attempt < MAX_RETRIES - 1:
                        self._append_output(
                            f"    ⏰ Zeitüberschreitung (Versuch {attempt + 1}/{MAX_RETRIES}). "
                            "Wiederhole mit längerem Timeout...\n",
                        )
                        continue

                except Exception as e:
                    last_exception = str(e)

                    if attempt < MAX_RETRIES - 1:
                        self._append_output(
                            f"    ⚠️ Fehler (Versuch {attempt + 1}/{MAX_RETRIES}): {e}. Wiederhole...\n",
                        )
                        time.sleep(1)
                        continue

            if success:
                updated_pkgs.append(pkg)
                self._append_output(f"  ✅ {pkg} aktualisiert.\n")

                module_name = pkg.replace("-", "_")
                try:
                    FastLazyLoader.clear_cache(module_name)
                except Exception as e:
                    logger.debug("Ignored exception: %s", e, exc_info=True)
            else:
                failed_pkgs.append(pkg)
                self._append_output(f"  ❌ {pkg} fehlgeschlagen: {last_exception}\n")

            time.sleep(0.05)

        self._update_progress(100, "Fertig")
        self._current_install_phase = InstallPhase.FINISHED

        report = f"\n✅ Kritische Pakete: {len(updated_pkgs)} aktualisiert"

        if failed_pkgs:
            report += f", {len(failed_pkgs)} fehlgeschlagen"
        if skipped_pkgs:
            report += f", {len(skipped_pkgs)} übersprungen"

        self._append_output(report + "\n")

        if failed_pkgs:
            self._append_output(
                "\nFehlgeschlagene Pakete:\n  • " + "\n  • ".join(failed_pkgs) + "\n",
            )

        if skipped_pkgs:
            self._append_output(
                "\nÜbersprungen (Blacklist):\n  • "
                + "\n  • ".join(skipped_pkgs)
                + "\n",
            )

        self._append_output("\n🔍 Prüfe Pydantic-Kompatibilität...\n")
        compatible, pv, cv = self._check_pydantic_compatibility()

        if not compatible and pv and cv:
            self._append_output(
                f"⚠️ Inkompatibilität erkannt (pydantic={pv}, core={cv}).\n"
                "   Führe automatische Reparatur durch...\n",
            )
            self._repair_pydantic_compatibility()
        else:
            self._append_output("✅ Pydantic-Kompatibilität OK.\n")

        self._enable_ui(True)

        if hasattr(self, "cancel_btn") and self.cancel_btn.winfo_exists():
            self.cancel_btn.config(state="disabled")

        self.status_var.set(f"✅ {len(updated_pkgs)} kritische Pakete aktualisiert")
        self._refresh_package_status()

        current = threading.current_thread()
        with self._active_threads_lock:
            try:
                self._active_threads.remove(current)
            except Exception as e:
                logger.debug("Ignored exception: %s", e, exc_info=True)

    def update_all_pip_packages(self) -> None:
        if self._update_running:
            self._append_output("⚠️ Ein Update läuft bereits – bitte warten.\n")
            return

        if not self.in_venv and not self._is_admin():
            self._append_output(
                "\n⚠️ Sie führen ein systemweites Update ohne venv durch.\n"
                "Dies kann Ihre Python‑Installation beschädigen.\n"
                "Empfehlung: Nutzen Sie eine virtuelle Umgebung (venv).\n\n",
            )

            if not DarkMessageBox.askyesno(
                "Systemweites Update",
                "Möchten Sie trotzdem fortfahren? (Nicht empfohlen)",
                parent=self.dialog,
            ):
                self._append_output("Update abgebrochen.\n")
                return

        self._update_running = True
        self._current_install_phase = InstallPhase.UPDATING_ALL

        self._append_output("\n📦 ALLE PIP-PAKETE AKTUALISIEREN\n")
        self._enable_ui(False)

        if hasattr(self, "cancel_btn") and self.cancel_btn.winfo_exists():
            self.cancel_btn.config(state="normal")

        self.status_var.set("⏳ Paketliste wird ermittelt...")

        supports_break_system = self._pip_supports_break_system()

        thread = threading.Thread(
            target=self._update_all_worker,
            args=(supports_break_system,),
            daemon=True,
            name="InstallDependency-UpdateWorker",
        )

        with self._active_threads_lock:
            self._active_threads.append(thread)

        thread.start()

    def _update_all_worker(self, supports_break_system: bool) -> None:
        python_exe = sys.executable

        self._append_output("📋 Ermittle veraltete Pakete...\n")

        cmd = [python_exe, "-m", "pip", "list", "--outdated", "--format=json"]

        try:
            result = subprocess.run(
                cmd,
                capture_output=True,
                text=True,
                timeout=60,
                check=False,
            )

            if result.returncode != 0:
                self._append_output(f"❌ pip list fehlgeschlagen: {result.stderr}\n")
                return

            outdated = json.loads(result.stdout)

        except subprocess.TimeoutExpired:
            self._append_output("❌ Zeitüberschreitung bei der Paketliste.\n")
            return
        except json.JSONDecodeError as e:
            self._append_output(f"❌ JSON‑Fehler in pip‑Ausgabe: {e}\n")
            return
        except Exception as e:
            self._append_output(f"❌ Fehler beim Ermitteln veralteter Pakete: {e}\n")
            return

        if not outdated:
            self._append_output("✅ Alle pip‑Pakete sind bereits aktuell.\n")
            self.status_var.set("✅ Alle Pakete aktuell")
            return

        packages = [pkg["name"] for pkg in outdated]
        total = len(packages)
        self._append_output(f"📦 {total} Pakete sind veraltet.\n")

        _size_cache = {}

        def _get_package_size(pkg: str) -> int | None:
            if pkg in _size_cache:
                return _size_cache[pkg]

            try:
                use_uv = shutil.which("uv") and not self._use_legacy_pip

                if use_uv:
                    dry_cmd = ["uv", "pip", "download", "--no-deps", "--dry-run", pkg]
                else:
                    dry_cmd = [
                        python_exe,
                        "-m",
                        "pip",
                        "download",
                        "--no-deps",
                        "--dry-run",
                        pkg,
                    ]

                proc = subprocess.run(
                    dry_cmd,
                    capture_output=True,
                    text=True,
                    timeout=30,
                    check=False,
                )

                match = re.search(
                    r"Downloading\s+\S+\s+\(([\d\.]+)\s+([KM]B)\)",
                    proc.stderr,
                )

                if match:
                    size = float(match.group(1))
                    unit = match.group(2)

                    if unit == "MB":
                        size *= 1024 * 1024
                    elif unit == "KB":
                        size *= 1024

                    _size_cache[pkg] = int(size)
                    return int(size)

            except Exception as e:
                logger.debug("Ignored exception: %s", e, exc_info=True)

            _size_cache[pkg] = None
            return None

        def _get_timeout_for_package(pkg_name: str) -> int:
            pkg_lower = pkg_name.lower()

            if any(x in pkg_lower for x in ("nvidia", "cuda", "cudnn")):
                return 900
            if pkg_lower in ("torch", "pytorch", "tensorflow", "transformers"):
                return 600
            if pkg_lower in ("pytorch-lightning", "stanza", "spacy", "thinc"):
                return 400
            if "opencv" in pkg_lower or "pillow" in pkg_lower:
                return 300
            if "scipy" in pkg_lower or "numpy" in pkg_lower:
                return 240
            if "grpcio" in pkg_lower or "protobuf" in pkg_lower:
                return 300
            return 180

        updated_pkgs = []
        failed_pkgs = []
        skipped_pkgs = []

        for idx, pkg in enumerate(packages, 1):
            if self._stop_event.is_set():
                self._append_output("⏹️ Update durch Benutzer abgebrochen.\n")
                break

            progress = int((idx - 1) / total * 100)
            self._update_progress(progress, f"Aktualisiere {pkg} ({idx}/{total})")
            self._append_output(f"\n📦 ({idx}/{total}) Aktualisiere {pkg}...\n")

            if pkg in self.UPDATE_BLACKLIST:
                self._append_output(
                    f"  ⏭️ überspringe {pkg} (systemkritisch / Blacklist)\n",
                )
                skipped_pkgs.append(pkg)
                continue

            size_bytes = _get_package_size(pkg)

            if size_bytes:
                size_mb = size_bytes / (1024 * 1024)
                self._append_output(f"  📦 Größe: ca. {size_mb:.1f} MB\n")
            else:
                self._append_output("  📦 Größe: unbekannt\n")

            use_uv = shutil.which("uv") and not self._use_legacy_pip

            if use_uv:
                cmd = ["uv", "pip", "install", "--upgrade", pkg]
            else:
                cmd = [
                    python_exe,
                    "-m",
                    "pip",
                    "install",
                    "--upgrade",
                    "--no-cache-dir",
                    "--disable-pip-version-check",
                ]

                if not self.in_venv:
                    if supports_break_system:
                        cmd.append("--break-system-packages")
                    else:
                        cmd.append("--user")

                cmd.append(pkg)

            timeout = _get_timeout_for_package(pkg)

            start_time = time.time()

            try:
                process = subprocess.Popen(
                    cmd,
                    stdout=subprocess.PIPE,
                    stderr=subprocess.STDOUT,
                    text=True,
                    bufsize=1,
                    universal_newlines=True,
                )

                last_update = start_time
                last_percent = 0
                total_downloaded = 0

                for line in iter(process.stdout.readline, ""):
                    if self._stop_event.is_set():
                        process.terminate()
                        self._append_output("  ⏹️ Abbruch durch Benutzer\n")
                        failed_pkgs.append(pkg)
                        break

                    line = line.strip()
                    if not line:
                        continue

                    percent_match = re.search(r"(\d+)%", line)

                    if percent_match:
                        percent = int(percent_match.group(1))

                        if percent > last_percent:
                            last_percent = percent

                            if size_bytes:
                                now = time.time()

                                if now - last_update >= 1.0:
                                    elapsed = now - start_time

                                    if elapsed > 0:
                                        total_downloaded = size_bytes * (
                                            percent / 100.0
                                        )
                                        speed = total_downloaded / elapsed / 1024
                                        eta_sec = (size_bytes - total_downloaded) / max(
                                            1,
                                            speed * 1024,
                                        )

                                        if eta_sec < 60:
                                            eta_display = f" (noch ca. {eta_sec:.0f}s)"
                                        elif eta_sec < 3600:
                                            eta_display = (
                                                f" (noch ca. {eta_sec / 60:.1f}min)"
                                            )
                                        else:
                                            eta_display = ""

                                        self._append_output(
                                            f"    Download: {percent}% – {speed:.0f} KB/s{eta_display}\r",
                                        )
                                        last_update = now
                                    else:
                                        self._append_output(
                                            f"    Download: {percent}%\r",
                                        )
                            else:
                                self._append_output(f"    Download: {percent}%\r")
                    elif (
                        "ERROR" in line
                        or "Successfully" in line
                        or "Installing" in line
                        or DEBUG_LEVEL >= 3
                    ):
                        self._append_output(f"    {line}\n")

                retcode = process.wait(timeout=timeout)
                duration = time.time() - start_time

                if retcode == 0:
                    updated_pkgs.append(pkg)
                    self._append_output(
                        f"  ✅ {pkg} aktualisiert (Dauer: {duration:.1f}s)\n",
                    )

                    module_name = pkg.replace("-", "_")
                    try:
                        FastLazyLoader.clear_cache(module_name)
                    except Exception as e:
                        logger.debug("Ignored exception: %s", e, exc_info=True)

                else:
                    failed_pkgs.append(pkg)
                    self._append_output(
                        f"  ❌ {pkg} fehlgeschlagen (Exit {retcode}, Dauer: {duration:.1f}s)\n",
                    )

                    if (
                        "externally-managed-environment"
                        in process.stdout.read().lower()
                    ):
                        self._append_output(
                            "    💡 Tipp: Verwenden Sie eine virtuelle Umgebung (venv).\n",
                        )
                    elif (
                        "subprocess-exited-with-error" in process.stdout.read().lower()
                    ):
                        self._append_output(
                            "    💡 Tipp: Ein C++ Compiler wird benötigt.\n",
                        )

            except subprocess.TimeoutExpired:
                process.kill()
                failed_pkgs.append(pkg)
                self._append_output(
                    f"  ⏰ Zeitüberschreitung bei {pkg} (>{timeout}s).\n",
                )

            except Exception as e:
                failed_pkgs.append(pkg)
                self._append_output(f"  ❌ {pkg}: {e}\n")

            time.sleep(0.2)

        self._update_progress(100, "Fertig")
        self._current_install_phase = InstallPhase.FINISHED

        report = f"\n✅ Update abgeschlossen: {len(updated_pkgs)} aktualisiert"

        if failed_pkgs:
            report += f", {len(failed_pkgs)} fehlgeschlagen"
        if skipped_pkgs:
            report += f", {len(skipped_pkgs)} übersprungen"

        self._append_output(report + "\n")

        if failed_pkgs:
            self._append_output(
                "\nFehlgeschlagene Pakete:\n  • " + "\n  • ".join(failed_pkgs) + "\n",
            )

        if skipped_pkgs:
            self._append_output(
                "\nÜbersprungen (Blacklist):\n  • "
                + "\n  • ".join(skipped_pkgs)
                + "\n",
            )

        self._append_output("\n🔍 Prüfe Pydantic-Kompatibilität...\n")
        compatible, pv, cv = self._check_pydantic_compatibility()

        if not compatible and pv and cv:
            self._append_output(
                f"⚠️ Inkompatibilität erkannt (pydantic={pv}, core={cv}).\n"
                "   Führe automatische Reparatur durch...\n",
            )
            self._repair_pydantic_compatibility()
        else:
            self._append_output("✅ Pydantic-Kompatibilität OK.\n")

        self._enable_ui(True)

        if hasattr(self, "cancel_btn") and self.cancel_btn.winfo_exists():
            self.cancel_btn.config(state="disabled")

        self.status_var.set(f"✅ {len(updated_pkgs)} Pakete aktualisiert")
        self._refresh_package_status()

        current = threading.current_thread()
        with self._active_threads_lock:
            try:
                self._active_threads.remove(current)
            except Exception as e:
                logger.debug("Ignored exception: %s", e, exc_info=True)

    def _run_subprocess(
        self,
        cmd: list[str],
        description: str = "",
        env: dict[str, str] | None = None,
        timeout: int = 120,
        stream_output: bool = True,
        cancel_event: threading.Event | None = None,
    ) -> str | None:
        if not cmd:
            self._append_output(f"⚠️ Leerer Befehl für {description} – überspringe.\n")
            return None

        effective_env = os.environ.copy()
        if env:
            effective_env.update(env)

        self._append_output(f"  🔧 {description}...\n")

        if DEBUG_LEVEL >= 3:
            log_debug("subprocess", f"  Befehl: {' '.join(cmd)}")

        proc = None
        stdout_lines = []
        stderr_lines = []
        time.perf_counter()
        self._last_stderr = ""

        try:
            proc = subprocess.Popen(
                cmd,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                stdin=subprocess.DEVNULL,
                text=True,
                encoding="utf-8",
                errors="replace",
                env=effective_env,
                creationflags=subprocess.CREATE_NO_WINDOW if IS_WINDOWS else 0,
                start_new_session=not IS_WINDOWS,
            )

            with self._process_lock:
                self._current_process = proc

            deadline = time.time() + timeout

            while True:
                if (
                    cancel_event and cancel_event.is_set()
                ) or self._stop_event.is_set():
                    self._append_output("    ⏹️ Befehl durch Benutzer abgebrochen.\n")
                    self._terminate_current_process()
                    return None

                retcode = proc.poll()

                if retcode is not None:
                    stdout, stderr = proc.communicate()

                    if stdout:
                        stdout_lines.extend(stdout.splitlines())
                    if stderr:
                        stderr_lines.extend(stderr.splitlines())
                    break

                if time.time() >= deadline:
                    self._append_output(f"    ⏰ Zeitüberschreitung nach {timeout}s\n")
                    self._terminate_current_process()
                    return None

                time.sleep(0.1)

            stdout_str = "\n".join(stdout_lines).strip()
            stderr_str = "\n".join(stderr_lines).strip()
            self._last_stderr = stderr_str

            if proc.returncode == 0:
                if stream_output and stdout_str:
                    for line in stdout_lines:
                        if line.strip():
                            self._append_output(f"    {line}\n")
                return stdout_str
            if stderr_str:
                self._append_output(
                    f"    ❌ Fehler (Exit {proc.returncode}): {stderr_str[:200]}\n",
                )
            else:
                self._append_output(
                    f"    ❌ Befehl fehlgeschlagen (Exit {proc.returncode})\n",
                )
            return None

        except FileNotFoundError:
            self._append_output(f"    ❌ Befehl nicht gefunden: {cmd[0]}\n")
            return None

        except PermissionError:
            self._append_output(f"    ❌ Keine Ausführungsberechtigung für {cmd[0]}\n")
            return None

        except Exception as e:
            self._append_output(f"    ❌ Unerwarteter Fehler: {e}\n")
            logger.exception(f"_run_subprocess Fehler: {e}")
            return None

        finally:
            with self._process_lock:
                self._current_process = None

            if proc and proc.poll() is None:
                self._terminate_current_process()

    def _terminate_current_process(self) -> None:
        with self._process_lock:
            proc = self._current_process

            if proc is None or proc.poll() is not None:
                return

            try:
                PlatformUtils.terminate_process(
                    proc,
                    child_terminate_timeout=1.0,
                    child_kill_wait=0.5,
                    parent_terminate_timeout=2.0,
                    parent_kill_wait=1.0,
                    fallback_terminate_timeout=1.0,
                    fallback_kill_wait=0.5,
                )

                if DEBUG_LEVEL >= 3:
                    log_debug("install_dlg", "Subprozess beendet")

            except Exception as e:
                self._append_output(f"Fehler beim Abbrechen: {e}\n")

            finally:
                self._current_process = None

    def cancel_installation(self) -> None:
        if DEBUG_LEVEL >= 2:
            log_debug("install_dlg", "cancel_installation aufgerufen")

        self._stop_event.set()
        self._terminate_current_process()

        self._append_output("\n⏹️ Abbruch durch Benutzer...\n")
        self._safe_after(0, self._perform_ui_reset)

    def _perform_ui_reset(self) -> None:
        if self._closed or not self.dialog.winfo_exists():
            return

        try:
            if self.cancel_btn.winfo_exists():
                self.cancel_btn.config(state="disabled")
        except Exception as e:
            logger.debug("Ignored exception: %s", e, exc_info=True)

        try:
            self._enable_ui(True)
        except Exception as e:
            logger.warning("_enable_ui fehlgeschlagen: %s", e)

        try:
            self.status_var.set("⏹️ Abgebrochen")
        except Exception as e:
            logger.debug("Ignored exception: %s", e, exc_info=True)

        if hasattr(self, "update_status_label"):
            try:
                if self.update_status_label.winfo_exists():
                    self.update_status_label.config(text="")
            except Exception as e:
                logger.debug("Ignored exception: %s", e, exc_info=True)

        self._current_install_phase = InstallPhase.CANCELLED

    def _restart_as_admin(self) -> None:
        if not IS_WINDOWS:
            self._append_output(
                "ℹ️ Neustart mit Admin-Rechten ist nur unter Windows nötig.\n",
            )
            return

        if self._is_admin():
            self._append_output("✅ Programm läuft bereits mit Administratorrechten.\n")
            return

        if getattr(self, "_restart_in_progress", False):
            self._append_output("⚠️ Neustart wird bereits durchgeführt.\n")
            return

        self._restart_in_progress = True
        self._append_output("🔄 Starte das Programm mit Administratorrechten neu...\n")

        def _perform_elevation():
            try:
                python_exe = sys.executable
                script_path = os.path.abspath(sys.argv[0])

                import shlex

                quoted_args = [shlex.quote(arg) for arg in sys.argv[1:]]
                arg_string = " ".join(quoted_args)

                ps_command = (
                    f"Start-Process -FilePath '{python_exe}' "
                    f"-ArgumentList '{script_path} {arg_string}' "
                    f"-Verb RunAs -WindowStyle Normal"
                )

                if DEBUG_LEVEL >= 3:
                    log_debug("admin_restart", f"PowerShell-Befehl: {ps_command}")

                startupinfo = subprocess.STARTUPINFO()
                startupinfo.dwFlags |= subprocess.STARTF_USESHOWWINDOW
                startupinfo.wShowWindow = subprocess.SW_HIDE

                proc = subprocess.Popen(
                    ["powershell", "-Command", ps_command],
                    shell=False,
                    startupinfo=startupinfo,
                    creationflags=subprocess.CREATE_NO_WINDOW,
                )

                time.sleep(0.3)

                if proc.poll() is not None:
                    self._append_output(
                        "❌ PowerShell-Befehl konnte nicht gestartet werden.\n",
                    )
                    self._restart_in_progress = False
                    return

                self._append_output(
                    "✅ Neustart mit Adminrechten wurde angefordert.\n"
                    "Das Programm wird nun beendet. Das neue Fenster öffnet sich in Kürze.\n",
                )
                self._exit_after_restart()

            except Exception as e:
                self._append_output(f"❌ Fehler beim Neustart (PowerShell): {e}\n")
                logger.exception("Fehler in _perform_elevation (PowerShell): %s", e)

                self._append_output("🔄 Versuche Fallback mit ShellExecuteW...\n")

                try:
                    import ctypes

                    ctypes.windll.shell32.ShellExecuteW(
                        None,
                        "runas",
                        python_exe,
                        f'"{script_path}"',
                        None,
                        1,
                    )

                    self._append_output(
                        "✅ ShellExecuteW erfolgreich. Programm wird beendet.\n",
                    )
                    self._exit_after_restart()

                except Exception as e2:
                    self._append_output(f"❌ Auch ShellExecuteW fehlgeschlagen: {e2}\n")
                    self._restart_in_progress = False

                    DarkMessageBox.showerror(
                        "Neustart fehlgeschlagen",
                        f"Das Programm konnte nicht mit Administratorrechten neu gestartet werden.\n\n"
                        f"Bitte starten Sie das Programm manuell als Administrator.\n\n"
                        f"Fehlerdetails:\n{str(e2)[:200]}",
                        parent=self.dialog,
                    )

        if self.dialog and self.dialog.winfo_exists():
            self.dialog.after(500, _perform_elevation)
        else:
            threading.Timer(0.5, _perform_elevation).start()

    def _exit_after_restart(self) -> None:
        if getattr(self, "_exiting", False):
            return

        self._exiting = True

        try:
            if self.dialog and self.dialog.winfo_exists():
                self.dialog.destroy()
        except Exception as e:
            logger.debug("Ignored exception: %s", e, exc_info=True)

        try:
            sys.exit(0)
        except SystemExit:
            raise
        except Exception as e:
            logger.error(f"Fehler beim Beenden: {e}")
            os._exit(0)

    # ─── Schließen ──────────────────────────────────────────────────────

    def close(self) -> None:
        if self._closed:
            return

        if DEBUG_LEVEL >= 2:
            log_debug("install_dlg", "close() aufgerufen – fahre herunter")

        self._closed = True
        self._stop_event.set()
        self._terminate_current_process()

        try:
            if self.dialog and self.dialog.winfo_exists():
                self.dialog.grab_release()
        except Exception as e:
            logger.debug("Ignored exception: %s", e, exc_info=True)

        try:
            if self.dialog and self.dialog.winfo_exists():
                self.dialog.withdraw()
        except Exception as e:
            logger.debug("Ignored exception: %s", e, exc_info=True)

        def _finalize_close():
            with self._active_threads_lock:
                threads_snapshot = list(self._active_threads)

            for t in threads_snapshot:
                if t.is_alive():
                    try:
                        t.join(timeout=1.0)
                    except Exception as e:
                        logger.debug("Ignored exception: %s", e, exc_info=True)

            with self._active_threads_lock:
                self._active_threads.clear()

            if self._executor is not None and not self._executor_shutdown:
                try:
                    self._executor.shutdown(wait=False, cancel_futures=True)
                    self._executor_shutdown = True
                except Exception as e:
                    logger.debug("Ignored exception: %s", e, exc_info=True)

            self._safe_after(0, lambda: super().close())

        threading.Thread(
            target=_finalize_close,
            daemon=True,
            name="InstallDlg-CloseWorker",
        ).start()


