    def _setup_callbacks(self) -> None:
        """Platzhalter für zusätzliche Callbacks (z. B. für Plugins)."""

    def _setup_validation_styles(self) -> None:
        """Erstellt ttk‑Styles für Validierungsfehler."""
        style = ttk.Style()
        style.configure("Danger.TSpinbox", fieldbackground="#ffcccc")
        style.configure("Danger.TEntry", fieldbackground="#ffcccc")
        style.configure("Danger.TCombobox", fieldbackground="#ffcccc")

    def _bind_validation_recursive(self, widget: tk.Widget) -> None:
        """Bindet Validierungsfunktionen an alle numerischen Widgets im Widget-Baum."""
        try:
            if not widget.winfo_exists():
                return
        except tk.TclError:
            return

        try:
            if isinstance(widget, (tk.Spinbox, tk.Entry, ttk.Entry)):
                var = self._spinbox_vars.get(widget)
                if var is not None and isinstance(var, (tk.DoubleVar, tk.IntVar)):
                    min_val, max_val = self._get_spinbox_range(widget)
                    is_int = isinstance(var, tk.IntVar)

                    def _on_focus_in(event, w=widget, v=var):
                        try:
                            w._saved_value = v.get()
                        except Exception as e:
                            logger.debug("Ignored exception: %s", e, exc_info=True)

                    widget.bind("<FocusIn>", _on_focus_in, add="+")

                    def _on_focus_out(
                        event,
                        w=widget,
                        v=var,
                        mn=min_val,
                        mx=max_val,
                        ii=is_int,
                    ):
                        self._validate_numeric_input(w, v, mn, mx, ii)

                    widget.bind("<FocusOut>", _on_focus_out, add="+")
        except Exception as e:
            logger.debug("Ignored exception: %s", e, exc_info=True)
        except Exception as e:
            logger.warning(f"Fehler beim Binden der Validierung für {widget}: {e}")
        try:
            for child in widget.winfo_children():
                self._bind_validation_recursive(child)
        except Exception as e:
            logger.debug("Ignored exception: %s", e, exc_info=True)

    def _get_spinbox_range(self, spin: tk.Spinbox) -> tuple[float, float]:
        """Ermittelt den gültigen Bereich einer Spinbox."""
        try:
            from_val = float(spin.cget("from"))
            to_val = float(spin.cget("to"))
            return from_val, to_val
        except Exception:
            return -float("inf"), float("inf")

    def _validate_numeric_input(
        self,
        widget: tk.Widget,
        var: tk.Variable,
        min_val: float,
        max_val: float,
        is_int: bool = False,
    ) -> bool:
        """Validiert eine numerische Eingabe und stellt bei Fehlern den letzten gültigen Wert wieder her."""
        try:
            raw = var.get()
        except tk.TclError:
            self._show_validation_error(widget, "Wert kann nicht gelesen werden")
            self.dialog.bell()
            return False

        saved = getattr(widget, "_saved_value", None)
        try:
            value = int(raw) if is_int else float(raw)
        except (ValueError, TypeError, OverflowError):
            if saved is not None:
                try:
                    var.set(saved)
                except Exception as e:
                    logger.debug("Ignored exception: %s", e, exc_info=True)
                self._clear_validation_error(widget)
            else:
                self._show_validation_error(widget, "Ungültige Zahl")
            self.dialog.bell()
            return False

        if not (min_val <= value <= max_val):
            if saved is not None:
                try:
                    var.set(saved)
                except Exception as e:
                    logger.debug("Ignored exception: %s", e, exc_info=True)
                self._clear_validation_error(widget)
            else:
                self._show_validation_error(
                    widget,
                    f"Wert muss zwischen {min_val} und {max_val} liegen",
                )
            self.dialog.bell()
            return False

        self._clear_validation_error(widget)
        return True

    def _validate_suppress_tokens(self, value: str) -> bool:
        """Validiert das Format des Feldes ``suppress_tokens``."""
        if value is None:
            if DEBUG_LEVEL >= 4:
                log_debug(
                    "validate",
                    "_validate_suppress_tokens: value ist None → gültig (-1)",
                )
            return True

        if not isinstance(value, str):
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "validate",
                    f"_validate_suppress_tokens: value ist kein String (Typ {type(value).__name__}) → ungültig",
                )
            return False

        stripped = value.strip()
        if not stripped:
            if DEBUG_LEVEL >= 4:
                log_debug(
                    "validate",
                    "_validate_suppress_tokens: leerer String → gültig (-1)",
                )
            return True

        if stripped == "-1":
            if DEBUG_LEVEL >= 4:
                log_debug("validate", "_validate_suppress_tokens: '-1' → gültig")
            return True
        parts = [p.strip() for p in stripped.split(",")]
        if "" in parts:
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "validate",
                    f"_validate_suppress_tokens: leere Elemente in '{stripped}' → ungültig",
                )
            return False
        try:
            tokens = [int(part) for part in parts]
        except (ValueError, OverflowError) as e:
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "validate",
                    f"_validate_suppress_tokens: Konvertierungsfehler '{stripped}' → {e}",
                )
            return False
        if any(t < 0 for t in tokens):
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "validate",
                    f"_validate_suppress_tokens: negative Werte in '{stripped}' → ungültig",
                )
            return False
        if DEBUG_LEVEL >= 4:
            log_debug(
                "validate",
                f"_validate_suppress_tokens: '{stripped}' → {len(tokens)} Token(s), gültig",
            )
        return True

    def _validate_suppress_field(self) -> None:
        """Validiert das »Suppress Tokens«‑Eingabefeld bei Fokusverlust und
        markiert es bei ungültigen Eingaben rot.  Die Methode ist robust
        gegen den Fall, dass das zugehörige Widget (noch) nicht existiert
        (Lazy Loading des Tabs »Erweitert & System«).
        """
        # ── 1. Konstante für maximalen Token‑ID‑Bereich ─────────────────────
        WHISPER_MAX_TOKEN_ID = 50256  # Standard‑Token‑Vokabular von Whisper

        widget = getattr(self, "suppress_entry", None)
        if widget is None:
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "validate",
                    "_validate_suppress_field: suppress_entry widget nicht vorhanden – Abbruch",
                )
            return

        try:
            if not widget.winfo_exists():
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "validate",
                        "_validate_suppress_field: suppress_entry widget existiert nicht mehr – Abbruch",
                    )
                return
        except (tk.TclError, AttributeError):
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "validate",
                    "_validate_suppress_field: TclError/AttributeError bei winfo_exists – Abbruch",
                )
            return

        try:
            tokens_str = self.suppress_tokens_var.get().strip()
        except tk.TclError:
            logger.warning("_validate_suppress_field: suppress_tokens_var nicht lesbar")
            return

        if not tokens_str:
            self._clear_validation_error(widget)
            if DEBUG_LEVEL >= 4:
                log_debug(
                    "validate",
                    "_validate_suppress_field: leeres Feld → als -1 interpretiert, gültig",
                )
            return

        # ── 3. Validierung durchführen ──────────────────────────────────────
        is_valid, error_msg = self._validate_suppress_tokens(
            tokens_str,
            min_token=0,
            max_token=WHISPER_MAX_TOKEN_ID,
        )

        if is_valid:
            self._clear_validation_error(widget)
            if DEBUG_LEVEL >= 4:
                log_debug(
                    "validate",
                    "_validate_suppress_field: gültig – '%s'",
                    tokens_str[:60],
                )
        else:
            # ── 4. Fehlermeldung zusammenbauen ──────────────────────────────
            if error_msg:
                msg = f"Ungültige Eingabe: {error_msg}\n\n"
            else:
                msg = "Ungültiges Format.\n\n"
            msg += (
                "Erwartet wird eine kommagetrennte Liste von Token‑IDs "
                "im Bereich 0‑50256.\n"
                "Beispiele: -1  oder  1,2,3  oder  10-20,100\n"
                "Hinweis: -1 bedeutet Standard‑Unterdrückung (empfohlen)."
            )
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "validate",
                    "_validate_suppress_field: ungültig – '%s' → %s",
                    tokens_str[:60],
                    error_msg,
                )
            self._show_validation_error(widget, msg)

    def _validate_suppress_tokens(
        self,
        token_str: str,
        min_token: int = 0,
        max_token: int = 50256,
    ) -> tuple[bool, str]:
        """Validiert einen kommagetrennten String von Token‑IDs und optionalen Bereichen."""
        # ── 1. Leerer String oder "-1" → sofort gültig ──────────────────────
        if not token_str or token_str.strip() == "-1":
            return True, ""

        # ── 2. String in einzelne Teile zerlegen ─────────────────────────────
        parts = [p.strip() for p in token_str.split(",") if p.strip()]
        if not parts:
            return False, "Keine Token‑IDs angegeben."

        # ── 3. Hilfsfunktion für Bereichsvalidierung ─────────────────────────
        def validate_token_id(value: int) -> tuple[bool, str]:
            if value < min_token:
                return False, f"Token {value} ist kleiner als {min_token}."
            if value > max_token:
                return False, f"Token {value} ist größer als {max_token}."
            return True, ""

        # ── 4. Jedes Teil validieren ──────────────────────────────────────────
        for part in parts:
            # 4a. Bereich (z.B. "10-20")
            if "-" in part and not part.startswith("-"):
                try:
                    start_str, end_str = part.split("-", 1)
                    start = int(start_str.strip())
                    end = int(end_str.strip())
                except ValueError:
                    return False, f"Ungültiger Bereich: '{part}' – keine ganzen Zahlen."

                if start < min_token or start > max_token:
                    return (
                        False,
                        f"Startwert {start} außerhalb des gültigen Bereichs [{min_token}, {max_token}].",
                    )
                if end < min_token or end > max_token:
                    return (
                        False,
                        f"Endwert {end} außerhalb des gültigen Bereichs [{min_token}, {max_token}].",
                    )
                if start > end:
                    return False, f"Startwert {start} ist größer als Endwert {end}."

                # Optional: Prüfen, ob der Bereich zu groß ist (> 10000 Elemente)
                if end - start > 10000:
                    return (
                        False,
                        f"Bereich '{part}' umfasst über 10000 Token – zu groß.",
                    )

            # 4b. Einzelne ID
            else:
                try:
                    token_id = int(part)
                except ValueError:
                    return False, f"Ungültige Token‑ID: '{part}' – keine ganze Zahl."

                valid, msg = validate_token_id(token_id)
                if not valid:
                    return False, msg

        # ── 5. Alle Prüfungen bestanden ──────────────────────────────────────
        return True, ""

    def _validate_proxy_url(self, url: str) -> bool:
        """Prüft, ob die Proxy‑URL ein gültiges Schema und netloc hat."""
        if not url:
            return False
        try:
            parsed = urllib.parse.urlparse(url)
            return parsed.scheme in ("http", "https", "socks4", "socks5") and bool(
                parsed.netloc,
            )
        except Exception:
            return False

    def _validate_proxy_field(self) -> None:
        """Validiert die Proxy‑URL bei Fokusverlust und markiert das Feld bei
        ungültigen Eingaben rot.  Die Methode ist robust gegen den Fall,
        dass das zugehörige Widget (noch) nicht existiert (Lazy Loading
        des Tabs »Erweitert & System«).
        """
        widget = getattr(self, "proxy_entry", None)
        if widget is None:
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "validate",
                    "_validate_proxy_field: proxy_entry widget nicht vorhanden – Abbruch",
                )
            return
        try:
            if not widget.winfo_exists():
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "validate",
                        "_validate_proxy_field: proxy_entry widget existiert nicht mehr – Abbruch",
                    )
                return
        except (tk.TclError, AttributeError):
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "validate",
                    "_validate_proxy_field: TclError/AttributeError bei winfo_exists – Abbruch",
                )
            return
        try:
            proxy_enabled = self.proxy_enabled_var.get()
        except tk.TclError:
            logger.warning("_validate_proxy_field: proxy_enabled_var nicht lesbar")
            return
        try:
            url = self.proxy_var.get().strip()
        except tk.TclError:
            logger.warning("_validate_proxy_field: proxy_var nicht lesbar")
            return
        if not proxy_enabled or not url:
            self._clear_validation_error(widget)
            return
        is_valid = self._validate_proxy_url(url)
        if is_valid:
            self._clear_validation_error(widget)
            if DEBUG_LEVEL >= 4:
                log_debug(
                    "validate",
                    "_validate_proxy_field: gültig – '%s'",
                    url[:60],
                )
        else:
            try:
                parsed = urllib.parse.urlparse(url)
                if not parsed.scheme:
                    msg = (
                        "Ungültiges URL‑Schema. Erlaubt sind:\n"
                        "http, https, socks4, socks5."
                    )
                elif not parsed.netloc:
                    msg = (
                        "Proxy‑Adresse enthält keinen Hostnamen.\n"
                        "Beispiel: socks5://127.0.0.1:18080"
                    )
                else:
                    msg = (
                        "Proxy‑URL ist ungültig. Bitte Format prüfen.\n"
                        "Beispiel: socks5://127.0.0.1:18080"
                    )
            except Exception:
                msg = "Proxy‑URL ist ungültig. Bitte Format prüfen."
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "validate",
                    "_validate_proxy_field: ungültig – '%s'",
                    url[:60],
                )
            self._show_validation_error(widget, msg)

    def _show_validation_error(
        self,
        widget: tk.Widget,
        message: str,
        play_bell: bool = True,
    ) -> None:
        """Markiert ein Widget visuell als fehlerhaft und speichert die
        zugehörige Fehlermeldung im internen ``_validation_errors``‑Dictionary.
        """
        self._validation_errors[widget] = message

        if DEBUG_LEVEL >= 4:
            log_debug(
                "validate",
                f"_show_validation_error: widget={widget!r}, "
                f"msg='{message}', bell={play_bell}",
            )

        if play_bell:
            try:
                if hasattr(self, "dialog") and self.dialog.winfo_exists():
                    self.dialog.bell()
                else:
                    widget.bell()
            except Exception as e:
                logger.debug("Ignored exception: %s", e, exc_info=True)
            except Exception as e:
                logger.warning(f"_show_validation_error: bell() fehlgeschlagen: {e}")

        try:
            if not widget.winfo_exists():
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "validate",
                        f"Widget {widget!r} existiert nicht mehr – "
                        "überspringe visuelle Markierung",
                    )
                return
        except tk.TclError:
            return

        ERROR_BG = "#ffcccc"

        try:
            if isinstance(widget, tk.Spinbox):
                widget.config(bg=ERROR_BG)

            elif isinstance(widget, ttk.Entry):
                widget.configure(style="Danger.TEntry")

            elif isinstance(widget, ttk.Combobox):
                style = ttk.Style()
                style.configure("Danger.TCombobox", fieldbackground=ERROR_BG)
                widget.configure(style="Danger.TCombobox")

            elif isinstance(widget, (tk.Entry, tk.Text)):
                widget.config(bg=ERROR_BG)

            else:
                try:
                    widget.config(bg=ERROR_BG)
                except Exception as e:
                    logger.debug("Ignored exception: %s", e, exc_info=True)

        except Exception as e:
            logger.debug("Ignored exception: %s", e, exc_info=True)
        except Exception as e:
            logger.warning(
                f"_show_validation_error: Fehler bei visueller Markierung "
                f"von {widget}: {e}",
            )
            if DEBUG_LEVEL >= 3:
                log_exception(
                    "validate",
                    "show_validation_error visual mark failed",
                    e,
                    level="debug",
                )

    def _clear_validation_error(self, widget: tk.Widget) -> None:
        """Entfernt die visuelle Fehlermarkierung von einem Widget und löscht
        den zugehörigen Eintrag aus dem internen ``_validation_errors``‑Dictionary.
        """
        if widget in self._validation_errors:
            removed_msg = self._validation_errors.pop(widget)
            if DEBUG_LEVEL >= 4:
                log_debug(
                    "validate",
                    f"_clear_validation_error: Fehler für {widget!r} "
                    f"entfernt (Meldung='{removed_msg}')",
                )
        elif DEBUG_LEVEL >= 4:
            log_debug(
                "validate",
                f"_clear_validation_error für {widget!r} aufgerufen, "
                "aber kein Fehlereintrag vorhanden",
            )

        try:
            if not widget.winfo_exists():
                return
        except tk.TclError:
            return

        try:
            theme = self.gui.current_theme
            normal_bg = getattr(theme, "BG_TERTIARY", "#f0f0f0")
            input_bg = getattr(
                theme,
                "INPUT_BG",
                getattr(theme, "BG_TERTIARY", "#f0f0f0"),
            )
        except Exception:
            normal_bg = "#f0f0f0"
            input_bg = "#f0f0f0"

        try:
            if isinstance(widget, tk.Spinbox):
                widget.config(bg=normal_bg)

            elif isinstance(widget, ttk.Entry):
                widget.state(["!invalid"])
                widget.configure(style="TEntry")

            elif isinstance(widget, ttk.Combobox):
                widget.configure(style="Dark.TCombobox")

            elif isinstance(widget, (tk.Entry, tk.Text)):
                widget.config(bg=input_bg)

            else:
                try:
                    widget.config(bg=input_bg)
                except Exception as e:
                    logger.debug("Ignored exception: %s", e, exc_info=True)

        except Exception as e:
            logger.debug("Ignored exception: %s", e, exc_info=True)
        except Exception as e:
            logger.warning(
                f"_clear_validation_error: Fehler bei visueller "
                f"Zurücksetzung von {widget}: {e}",
            )
            if DEBUG_LEVEL >= 3:
                log_exception(
                    "validate",
                    "clear_validation_error visual reset failed",
                    e,
                    level="debug",
                )

    def _on_search_changed(self) -> None:
        """Reagiert auf Änderungen im Suchfeld.  Durchsucht zuerst die bereits
        geladenen Tabs und anschließend den Index der noch nicht geladenen
        Tabs.
        """
        raw = self._search_text.get()
        term = raw.strip().lower() if raw else ""

        if not term:
            if DEBUG_LEVEL >= 4:
                log_debug("search", "_on_search_changed: kein Suchtext – Abbruch")
            return

        if DEBUG_LEVEL >= 3:
            log_debug("search", f"_on_search_changed: term='{term}'")

        try:
            tab_ids = self.notebook.tabs()
        except tk.TclError:
            if DEBUG_LEVEL >= 3:
                log_debug("search", "  notebook.tabs() fehlgeschlagen – Abbruch")
            return

        for tab_id in tab_ids:
            try:
                tab_widget = self.notebook.nametowidget(tab_id)
            except tk.TclError:
                continue

            if self._widget_contains_text(tab_widget, term):
                tab_idx = self.notebook.index(tab_id)
                self.notebook.select(tab_idx)
                self._flash_tab(tab_idx)
                self._highlight_search_widget(tab_widget, term)
                if DEBUG_LEVEL >= 3:
                    tab_text = self.notebook.tab(tab_id, "text")
                    log_debug("search", f"  Treffer in geladenem Tab '{tab_text}'")
                return

        idx = getattr(self, "_search_index", None)
        if idx is None:
            if DEBUG_LEVEL >= 3:
                log_debug("search", "  Kein _search_index vorhanden – Ende")
            return

        for tab_name, texts in idx.items():
            if tab_name in self._loaded_tabs:
                continue

            if any(term in t.lower() for t in texts):
                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "search",
                        f"  Index-Treffer für Tab '{tab_name}' – löse Lazy Load aus",
                    )

                tab_widget = self._get_tab_widget_by_name(tab_name)
                if tab_widget is None:
                    continue

                try:
                    pos = self.notebook.index(tab_widget)
                except tk.TclError:
                    continue

                self.notebook.select(pos)
                self._flash_tab(pos)

                def _highlight_after_load(tab=tab_widget, t=term):
                    self._highlight_search_widget(tab, t)

                if self.dialog and self.dialog.winfo_exists():
                    self.dialog.after(50, _highlight_after_load)

                if self.dialog and self.dialog.winfo_exists():
                    self.dialog.after(100, self._on_search_changed)

                return

        if DEBUG_LEVEL >= 3:
            log_debug("search", "  Kein Treffer im Index")

    def _add_to_search_index(self, tab_name: str, texts: list[str]) -> None:
        """Fügt dem internen Suchindex statische Texte für ein Tab hinzu."""
        if not tab_name:
            logger.warning("_add_to_search_index: leerer tab_name – ignoriert")
            return
        if not texts:
            if DEBUG_LEVEL >= 4:
                log_debug(
                    "search",
                    f"_add_to_search_index: '{tab_name}' – leere Textliste",
                )
            return

        if tab_name in self._loaded_tabs:
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "search",
                    f"_add_to_search_index: Tab '{tab_name}' bereits geladen – "
                    "Indexeintrag wird nicht mehr benötigt",
                )
            return

        idx: dict[str, list[str]] = getattr(self, "_search_index", None)
        if idx is None:
            self._search_index = {}
            idx = self._search_index
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "search",
                    "_add_to_search_index: _search_index neu initialisiert",
                )

        normalized = [t.strip().lower() for t in texts if t and t.strip()]
        if not normalized:
            if DEBUG_LEVEL >= 4:
                log_debug(
                    "search",
                    f"_add_to_search_index: '{tab_name}' – keine gültigen Texte nach Normalisierung",
                )
            return

        if tab_name not in idx:
            idx[tab_name] = []
        before = len(idx[tab_name])
        idx[tab_name].extend(normalized)
        after = len(idx[tab_name])

        if DEBUG_LEVEL >= 3:
            log_debug(
                "search",
                f"_add_to_search_index: '{tab_name}' +{after - before} Begriffe → {after} insgesamt",
            )

    def _get_tab_widget_by_name(self, name: str) -> tk.Widget | None:
        """Liefert das zu einem internen Tab‑Namen gehörende Frame-Widget."""
        try:
            return getattr(self, f"tab_{name}")
        except AttributeError:
            if DEBUG_LEVEL >= 3:
                log_debug("search", f"  Kein Widget für Tab '{name}'")
            return None

    def _widget_contains_text(self, widget: tk.Widget, term: str) -> bool:
        """Rekursiv prüfen, ob ein Widget oder seine Kinder den Suchbegriff enthalten."""
        if isinstance(widget, (tk.Label, tk.Checkbutton, tk.Radiobutton, tk.Button)):
            if term in widget.cget("text").lower():
                return True
        elif isinstance(widget, (tk.Entry, ttk.Entry, tk.Spinbox, ttk.Combobox)):
            try:
                if term in widget.get().lower():
                    return True
            except Exception as e:
                logger.debug("Ignored exception: %s", e, exc_info=True)
        for child in widget.winfo_children():
            if self._widget_contains_text(child, term):
                return True
        return False

    def _flash_tab(self, tab_idx: int) -> None:
        """Hebt das ausgewählte Tab kurz hervor."""
        style = ttk.Style()
        style.configure("Flash.TNotebook.Tab", background="#ffff99")
        self.notebook.tab(tab_idx, style="Flash.TNotebook.Tab")
        self.dialog.after(
            300,
            lambda: self.notebook.tab(tab_idx, style="TNotebook.Tab"),
        )

    def _show_advanced_search(self) -> None:
        """Öffnet einen Hinweis‑Dialog, der die Bedienung der Suche erklärt.
        Der aktuelle Suchtext (falls vorhanden) wird in die Meldung
        übernommen, sodass der Anwender ihn nicht erneut eintippen muss.
        """
        term = self._search_text.get().strip()
        info = (
            "Geben Sie einen Suchbegriff ein und drücken Sie die Eingabetaste.\n"
            "Alle Labels, Tooltips und Eingabefelder werden durchsucht.\n"
            "Bei einem Treffer wird das entsprechende Tab geöffnet und das\n"
            "erste passende Widget kurz hervorgehoben.\n\n"
            "Tipp: Verwenden Sie die Suche, um schnell zu einer bestimmten\n"
            "Einstellung zu springen (z. B. 'Proxy', 'VAD', 'Beam Size')."
        )
        if term:
            info = f"Aktuelle Suche: »{term}«\n\n{info}"

        try:
            DarkMessageBox.showinfo(
                "Erweiterte Suche",
                info,
                parent=self.dialog,
                timeout=30,
            )
        except Exception as e:
            logger.warning(
                "_show_advanced_search: Dialog konnte nicht geöffnet werden – %s\n%s",
                e,
                info,
            )
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "search",
                    f"_show_advanced_search: Fallback auf Log-Ausgabe wegen {e}",
                )

    def _highlight_search_widget(self, parent_widget: tk.Widget, term: str) -> None:
        """Sucht rekursiv (iterativ) im Widget‑Baum ab *parent_widget* nach
        einem Steuerelement, dessen sichtbarer Text den Suchbegriff
        *term* enthält, und hebt das erste gefundene Widget kurz optisch
        hervor (gelber Hintergrund), um dem Benutzer die Navigation zu
        erleichtern.
        """
        term_lower = term.lower()
        stack: list[tk.Widget] = [parent_widget]

        while stack:
            widget = stack.pop()
            try:
                if not widget.winfo_exists():
                    continue
            except tk.TclError:
                continue

            text = ""
            try:
                if isinstance(
                    widget,
                    (tk.Label, tk.Checkbutton, tk.Radiobutton, tk.Button),
                ):
                    text = widget.cget("text")
                elif isinstance(
                    widget,
                    (tk.Entry, ttk.Entry, tk.Spinbox, ttk.Combobox),
                ):
                    text = widget.get()
                elif isinstance(widget, tk.Text):
                    try:
                        text = widget.get("1.0", "2.0")
                    except Exception as e:
                        logger.debug("Ignored exception: %s", e, exc_info=True)
            except Exception as e:
                logger.debug("Ignored exception: %s", e, exc_info=True)
            except Exception as e:
                if DEBUG_LEVEL >= 4:
                    log_debug(
                        "search",
                        f"Fehler beim Auslesen von {type(widget).__name__}: {e}",
                    )

            if text and term_lower in text.lower():
                original_bg = ""
                try:
                    original_bg = widget.cget("bg")
                except Exception as e:
                    logger.debug("Ignored exception: %s", e, exc_info=True)

                try:
                    widget.config(bg="#ffff99")
                except tk.TclError:
                    return

                def restore():
                    try:
                        if widget.winfo_exists():
                            widget.config(bg=original_bg)
                    except Exception as e:
                        logger.debug("Ignored exception: %s", e, exc_info=True)
                    except Exception as e:
                        if DEBUG_LEVEL >= 4:
                            log_debug(
                                "search",
                                f"Fehler beim Zurücksetzen der Farbe: {e}",
                            )

                if self.dialog and self.dialog.winfo_exists():
                    self.dialog.after(800, restore)
                else:
                    restore()

                if DEBUG_LEVEL >= 3:
                    log_debug(
                        "search",
                        f"Widget {type(widget).__name__} hervorgehoben "
                        f"für Begriff '{term}'",
                    )
                return

            try:
                stack.extend(widget.winfo_children())
            except Exception as e:
                logger.debug("Ignored exception: %s", e, exc_info=True)

    def delete_current_profile(self) -> None:
        """Löscht das aktuell ausgewählte benutzerdefinierte Profil."""
        name = self.profile_var.get()
        if name not in self.custom_profiles:
            DarkMessageBox.showwarning(
                "Löschen nicht möglich",
                "Nur eigene Profile können gelöscht werden.",
                self.parent,
            )
            return
        if DarkMessageBox.askyesno(
            "Profil löschen",
            f"Möchten Sie das Profil '{name}' wirklich löschen?",
            parent=self.dialog,
        ):
            path = PlatformUtils.get_platform_config_dir() / "profiles" / f"{name}.json"
            try:
                path.unlink()
            except Exception as e:
                logger.debug("Ignored exception: %s", e, exc_info=True)
            if name in self.custom_profiles:
                del self.custom_profiles[name]
            self.profile_list.remove(name)
            self.profile_combo["values"] = self.profile_list
            self.profile_var.set("")
            DarkMessageBox.showinfo(
                "Gelöscht",
                f"Profil '{name}' wurde gelöscht.",
                self.parent,
            )

    def _on_theme_selected(self, event: tk.Event | None = None) -> None:
        """Wendet das ausgewählte Theme sofort als Live‑Vorschau an.

        Berücksichtigt, dass ttk-Widgets keine `bg`-Option unterstützen.
        """
        # ── 1. Grundlegende Prüfungen ─────────────────────────────────────
        if not hasattr(self, "dialog") or not self.dialog.winfo_exists():
            return

        new_theme = self.theme_var.get()
        if not new_theme:
            return

        gui = getattr(self, "gui", None)
        if gui is not None and hasattr(gui, "settings"):
            try:
                if gui.settings.theme == new_theme:
                    return
            except Exception:
                pass

        if DEBUG_LEVEL >= 2:
            log_debug("settings", f"Theme-Wechsel zu '{new_theme}'")

        # ── 2. Fenster kurz verstecken (Flackerschutz) ───────────────────
        try:
            self.dialog.withdraw()
        except Exception:
            pass

        # ── 3. Theme global setzen (über GUI) ────────────────────────────
        if gui is not None and hasattr(gui, "_apply_theme"):
            try:
                gui._apply_theme(new_theme)
            except Exception as e:
                logger.warning(f"gui._apply_theme fehlgeschlagen: {e}")
        else:
            # Fallback: Theme nur für diesen Dialog
            theme_map = {
                "dark": DarkTheme,
                "light": LightTheme,
                "pastel": PastelTheme,
                "highcontrast": HighContrastTheme,
                "dracula": DraculaTheme,
                "nord": NordTheme,
                "solarized": SolarizedDarkTheme,
                "gruvbox": GruvboxDarkTheme,
                "onedark": OneDarkTheme,
                "monokai": MonokaiTheme,
                "a11y-dark": A11yDarkTheme,
                "catppuccin": CatppuccinMochaTheme,
                "tokyonight": TokyoNightTheme,
            }
            theme_class = theme_map.get(new_theme, DarkTheme)
            try:
                if gui is not None:
                    gui.current_theme = theme_class()
            except Exception:
                pass

        try:
            theme = gui.current_theme if gui is not None else DarkTheme()
        except Exception:
            theme = DarkTheme()

        try:
            self.dialog.configure(bg=theme.BG_PRIMARY)
        except Exception:
            pass

        # ── 6. ttk-Styles aktualisieren ──────────────────────────────────
        try:
            self._setup_ttk_styles()
        except Exception as e:
            logger.warning(f"ttk-Styles-Update fehlgeschlagen: {e}")

        # ── 7. Widget-Baum aktualisieren (nur tk-Widgets) ──────────────
        try:
            PlatformUtils.apply_theme_to_widget_tree(self.dialog, theme)
        except Exception as e:
            logger.warning(f"Theme-Anwendung auf Widget-Baum fehlgeschlagen: {e}")

        # ── 8. Bereits geladene Tabs aktualisieren ──────────────────────
        if hasattr(self, "_loaded_tabs"):
            for tab_name in self._loaded_tabs:
                tab_attr = f"tab_{tab_name}"
                tab = getattr(self, tab_attr, None)
                if tab is None or not tab.winfo_exists():
                    continue
                try:
                    PlatformUtils.apply_theme_to_widget_tree(tab, theme)
                    tab.configure(bg=theme.BG_PRIMARY)
                except Exception:
                    pass

        # ── 9. Offene Nebendialoge aktualisieren ──────────────────────────
        if gui is not None and hasattr(gui, "_open_dialogs"):
            for dlg in gui._open_dialogs[:]:
                try:
                    if dlg is None or not dlg.winfo_exists():
                        continue
                    if hasattr(dlg, "apply_theme") and callable(dlg.apply_theme):
                        dlg.apply_theme()
                    elif isinstance(dlg, tk.Toplevel):
                        dlg.configure(bg=theme.BG_PRIMARY)
                        PlatformUtils.apply_theme_to_widget_tree(dlg, theme)
                except Exception:
                    pass

        tk_widgets = [
            "search_entry",
            "suppress_entry",
            "proxy_entry",
            "ollama_refresh_label",
        ]
        for name in tk_widgets:
            widget = getattr(self, name, None)
            if widget is None or not widget.winfo_exists():
                continue
            # Nur für tk-Widgets konfigurieren; ttk-Widgets werden via Style gesteuert
            if isinstance(widget, tk.Widget) and not isinstance(widget, ttk.Widget):
                try:
                    if isinstance(widget, tk.Entry):
                        widget.config(
                            bg=getattr(theme, "INPUT_BG", theme.BG_TERTIARY),
                            fg=theme.TEXT_PRIMARY,
                            insertbackground=theme.TEXT_PRIMARY,
                        )
                    elif isinstance(widget, tk.Label):
                        widget.config(
                            bg=theme.BG_PRIMARY,
                            fg=theme.TEXT_PRIMARY,
                        )
                    elif isinstance(widget, tk.Button):
                        widget.config(
                            bg=theme.BG_TERTIARY,
                            fg=theme.TEXT_PRIMARY,
                        )
                except Exception as e:
                    if DEBUG_LEVEL >= 3:
                        log_debug("settings", f"Fehler bei {name}: {e}")

        # ── 11. Canvas-Hintergründe ──────────────────────────────────────
        for canvas in getattr(self, "_scrollable_canvases", []):
            try:
                if canvas.winfo_exists():
                    canvas.configure(bg=theme.BG_PRIMARY)
            except Exception:
                pass

        # ── 12. GUI aktualisieren und Fenster wieder einblenden ──────────
        try:
            self.dialog.update_idletasks()
        except Exception:
            pass
        try:
            self.dialog.deiconify()
        except Exception:
            pass

        if DEBUG_LEVEL >= 3:
            log_debug("settings", f"Theme '{new_theme}' angewendet")

    def apply_theme(self) -> None:
        """Wird vom Hauptfenster bei globalen Theme‑Wechseln aufgerufen."""
        if not hasattr(self, "dialog") or not self.dialog.winfo_exists():
            return
        self._on_theme_selected()

