        self._shutdown_completed: bool = False
        self._dependency_issue: bool = False
        self._install_dialog_open: bool = False
        self._disposed: bool = False
        self._is_initialized: bool = False  # Wird am Ende der Init gesetzt

        self._status_lock: threading.RLock = threading.RLock()
        self._subscriptions_lock: threading.RLock = threading.RLock()
        self._duplicate_lock: threading.RLock = threading.RLock()
        self._tts_lock: threading.RLock = threading.RLock()
        self._translate_lock: threading.RLock = threading.RLock()
        self._history_lock: threading.RLock = threading.RLock()
        self._open_dialogs_lock: threading.RLock = threading.RLock()

        self._last_status_message: str = ""
        self._last_low_conf_warning_time: float = 0.0
