        self._last_activity_time: float = time.time()

        # ─── Letzte Texte (für Duplikaterkennung) ──────────────────────
        self._last_transcription_text: str = ""
        self._last_translation_text: str = ""
        self._last_output_translation: str = ""

        # ─── Geschichtspuffer ────────────────────────────────────────────
        self.transcript_history: deque = deque(maxlen=1000)
        self.translation_history: deque = deque(maxlen=500)
        self._open_dialogs: list[tk.Toplevel] = []

        # ─── TTS-Zustand ──────────────────────────────────────────────────
        self._tts_active: bool = False
        self._pending_tts_transcript: str = ""
        self._pending_tts_translation: str = ""
        self._tts_pending_count: int = 0
        self._last_tts_texts: deque = deque(maxlen=5)
        self._stopping_done: bool = False

        # ─── Layout- & Modus-Zustand ────────────────────────────────────
        self._current_layout: str | None = None
        self._live_mode_toggle_time: float = 0.0
        self._subtitle_anim_id: str | None = None
        self._progress_bar_started: bool = False

        # ─── Übersetzung ──────────────────────────────────────────────────
        self._translate_active: bool = True
        self.translate_active: bool = True
        self.subtitle_mode: bool = False

        # ─── Verarbeitungszustand ──────────────────────────────────────
        self.is_processing: bool = False
        self.demo_mode: bool = not WHISPER_AVAILABLE
        self.exit_confirmed: bool = False

        # ─── Stream-Informationen ──────────────────────────────────────
