        # ─── TTS-Callback-IDs für after_cancel ──────────────────────────
        self._tts_timer: str | None = None
        self._vram_idle_timer: str | None = None
        self._save_settings_timer: str | None = None

        # ─── Blacklist-Cache ────────────────────────────────────────────
        self._blacklist_regex_cache: dict[tuple, re.Pattern] = {}
        self._blacklist_cache_lock: threading.RLock = threading.RLock()
        self._blacklist_last_modified: float = 0.0

        self._already_flushed_texts: set[str] = set()
        self._flushed_combined_texts: set[str] = set()
