    @staticmethod
    def _get_global_cache_manager() -> CacheManager | None:
        """Holt den CacheManager aus dem globalen AppContext – oder None."""
        try:
            ctx = AppContext()
            return ctx.cache_manager
        except Exception as e:
            if DEBUG_LEVEL >= 3:
                log_debug(
                    "cache", "Could not retrieve CacheManager from AppContext: %s", e
                )
            return None

    def _init_cache_manager(self, cache_manager: CacheManager | None) -> None:
        """
        Initialisiert den CacheManager – mit klarer Priorität:
        1. Übergebener CacheManager
        2. Globaler AppContext (Singleton)
        3. Eigene, eigenständige Instanz (Fallback)
        """
        if cache_manager is not None:
            self._cache_manager = cache_manager
            return

        try:
            ctx = AppContext()
            if ctx.cache_manager is not None:
                self._cache_manager = ctx.cache_manager
                if DEBUG_LEVEL >= 3:
                    log_debug("cache", "Using CacheManager from global AppContext")
                return
        except Exception as e:
            if DEBUG_LEVEL >= 2:
                log_debug(
                    "cache", "Could not retrieve CacheManager from AppContext: %s", e
                )

        logger.warning(
            "⚠️ Kein CacheManager verfügbar – erstelle eigene Standalone‑Instanz."
        )
        self._cache_manager = CacheManager()

