def _show_user_error(message: str) -> None:
    if IS_WINDOWS and not sys.stdin.isatty():
        try:
            import ctypes

            ctypes.windll.user32.MessageBoxW(
                0,
                f"Dragon Whisperer - Setup Required\n\n{message}\n\n"
                "Please install missing components and try again.",
                "Setup Error",
                0x10,
            )
        except Exception as e:
            logger.debug("Ignored exception: %s", e, exc_info=True)
    elif "Tkinter" in message:
        print("\n💡 INSTALLATION HELP:")
        print("  pip install tk")
    elif "FFmpeg" in message:
        print("\n💡 INSTALLATION HELP:")
        if IS_WINDOWS:
            print("  Download from: https://ffmpeg.org/download.html")
        elif IS_MACOS:
            print("  brew install ffmpeg")
        else:
            print("  sudo apt install ffmpeg")
    else:
        print(f"\n❌ {message}")


def _fatal_error(message: str, title: str = "Fehler") -> None:
    """Gibt eine fatale Fehlermeldung aus."""
    logger.critical("%s: %s", title, message)
    if len(message) > 2000:
        message = message[:1997] + "..."
    if GUI_AVAILABLE:
        try:
            import tkinter.messagebox as mb

            root = None
            if tk._default_root is not None and tk._default_root.winfo_exists():
                root = tk._default_root
            if root is None:
                tmp_root = tk.Tk()
                tmp_root.withdraw()
                mb.showerror(title, message, parent=tmp_root)
                tmp_root.destroy()
            else:
                mb.showerror(title, message, parent=root)
            return
        except Exception as e:
            logger.debug("Tkinter‑MessageBox fehlgeschlagen: %s", e)
    if IS_WINDOWS:
        try:
            import ctypes

            ctypes.windll.user32.MessageBoxW(0, message, title, 0x10)
            return
        except Exception as e:
            logger.debug("Windows‑MessageBox fehlgeschlagen: %s", e)
    print(f"\n{'=' * 60}\n{title}\n{'=' * 60}\n{message}\n{'=' * 60}", file=sys.stderr)


